module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

    reg [2:0] current_state, next_state;

    localparam IDLE = 3'b000,
               S1   = 3'b001,
               S2   = 3'b010,
               S3   = 3'b011,
               S4   = 3'b100,
               S5   = 3'b101;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            IDLE: next_state = IN ? S1 : IDLE;
            S1:   next_state = IN ? S1 : S2;
            S2:   next_state = IN ? IDLE : S3;
            S3:   next_state = IN ? S4 : IDLE;
            S4:   next_state = IN ? S5 : IDLE;
            S5:   next_state = IN ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end


    always @(*) begin
        if (RST) begin
            MATCH = 1'b0;
        end else begin
            MATCH = (current_state == S5) && IN;
        end
    end

endmodule

