module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire wrstn,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata,
    input wire rclk,
    input wire rinc,
    input wire rrstn
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;

    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


    function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction

    assign wptr_gray = bin2gray(waddr_bin);
    assign rptr_gray = bin2gray(raddr_bin);


    reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync;
    always @(posedge wclk) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= {PTR_WIDTH{1'b0}};
            rptr_gray_sync <= {PTR_WIDTH{1'b0}};
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync <= rptr_gray_sync1;
        end
    end


    reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync;
    always @(posedge rclk) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= {PTR_WIDTH{1'b0}};
            wptr_gray_sync <= {PTR_WIDTH{1'b0}};
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync <= wptr_gray_sync1;
        end
    end


    wire full_cond, empty_cond;
    assign full_cond = (wptr_gray[PTR_WIDTH-1 -: 2] != rptr_gray_sync[PTR_WIDTH-1 -: 2]) &&
                       (wptr_gray[ADDR_WIDTH-1:0] == rptr_gray_sync[ADDR_WIDTH-1:0]);
    assign empty_cond = (rptr_gray == wptr_gray_sync);

    assign wfull = full_cond;
    assign rempty = empty_cond;


    wire wenc, renc;
    assign wenc = winc && !wfull;
    assign renc = rinc && !rempty;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH),
        .ADDR_WIDTH(ADDR_WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    always @(posedge wclk) begin
        if (!wrstn) begin
            waddr_bin <= {ADDR_WIDTH{1'b0}};
        end else if (wenc) begin
            waddr_bin <= waddr_bin + 1'b1;
        end
    end


    always @(posedge rclk) begin
        if (!rrstn) begin
            raddr_bin <= {ADDR_WIDTH{1'b0}};
        end else if (renc) begin
            raddr_bin <= raddr_bin + 1'b1;
        end
    end

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16,
    parameter ADDR_WIDTH = 4
) (
    input wire wclk,
    input wire wenc,
    input wire [ADDR_WIDTH-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [ADDR_WIDTH-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule

