module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;
reg [2:0] next_SP;

integer i;

always @(*) begin
    if (Rst) begin
        next_SP = 3'b100;

    end else if (EN) begin
        if (RW) begin 
            if (SP != 4)
                next_SP = SP + 1;
            else
                next_SP = SP;
        end else begin 
            if (SP != 0)
                next_SP = SP - 1;
            else
                next_SP = SP;
        end
    end else begin
        next_SP = SP;
    end
end

assign EMPTY = (next_SP == 4);
assign FULL = (next_SP == 0);

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;
        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        dataOut <= 4'b0;
    end else if (EN) begin
        if (RW) begin 
            if (SP != 4) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
            end
        end else begin 
            if (SP != 0) begin
                stack_mem[SP - 1] <= dataIn;
            end
        end
        SP <= next_SP;
    end
end

endmodule

