module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle    = 2'b00;
    parameter s1_red  = 2'b01;
    parameter s3_green= 2'b10;
    parameter s2_yellow=2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle:    next_state = s1_red;
            s1_red:  next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green:next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            case (state)
                s1_red:  cnt <= (cnt == 0) ? 10 : (next_state == s1_red) ? cnt - 1 : 10;
                s3_green: if (pass_request && (cnt > 10)) cnt <= 10;
                          else cnt <= (next_state == s3_green) ? cnt - 1 : 60;
                s2_yellow: cnt <= (next_state == s2_yellow) ? cnt - 1 : 5;
                default:   cnt <= cnt;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (next_state)
                s1_red: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                    p_red <= 1;
                    p_green <= 0;
                    p_yellow <= 0;
                end
                s3_green: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                    p_green <= 1;
                    p_red <= 0;
                    p_yellow <= 0;
                end
                s2_yellow: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                    p_red <= 0;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

