module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;
reg rise_flag;
reg down_flag;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 0;
        rise <= 0;
        down <= 0;
        rise_flag <= 0;
        down_flag <= 0;
    end else begin
        a_prev <= a;
        rise <= 0;
        down <= 0;


        if (a_prev == 0 && a == 1) begin
            rise_flag <= 1;
        end else if (a_prev == 1 && a == 0) begin
            down_flag <= 1;
        end


        if (rise_flag) begin
            rise <= 1;
            if (a_prev && !a) begin  
                down_flag <= 1;
                rise_flag <= 0;
            end
        end else if (down_flag) begin
            down <= 1;
            if (!a_prev && a) begin  
                rise_flag <= 1;
                down_flag <= 0;
            end
        end
    end
end

endmodule

