module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam CALCULATE = 2'b01;
    localparam DONE = 2'b10;

    reg [8:0] remainder;

    reg [7:0] quotient;

    reg [7:0] divisor_abs;
    reg [8:0] neg_divisor;
    reg dividend_sign;
    reg divisor_sign;
    reg [16:0] SR;

    reg [3:0] cnt;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            remainder <= 0;
            quotient <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            divisor_abs <= 0;
            SR <= 0;
            cnt <= 0;
            neg_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin
                        if (sign) begin
                            dividend_sign <= dividend[7];
                            divisor_sign <= divisor[7];
                            divisor_abs <= divisor[7] ? -divisor : divisor;
                            dividend_abs <= dividend[7] ? -dividend : dividend;
                        end else begin
                            dividend_sign <= 0;
                            divisor_sign <= 0;
                            divisor_abs <= divisor;
                            dividend_abs <= dividend;
                        end
                        neg_divisor <= -{1'b0, divisor_abs};
                        SR <= {({1'b0, dividend_abs} << 1), 8'b0};
                        cnt <= 1;
                        state <= CALCULATE;
                    end
                end

                CALCULATE: begin
                    if (cnt <= 8) begin

                        reg [8:0] temp_remainder;
                        temp_remainder = {remainder, quotient[7]} - neg_divisor;
                        if (temp_remainder[8] == 0) begin 
                            remainder <= temp_remainder[8:0];
                            quotient <= {quotient[6:0], 1'b1};
                        end else begin
                            quotient <= {quotient[6:0], 1'b0};
                        end
                        SR <= {remainder, quotient} << 1;
                        cnt <= cnt + 1;
                    end else begin

                        reg [7:0] rem, quo;
                        rem = remainder;
                        quo = quotient;
                        if (sign) begin
                            rem = dividend_sign ? -rem : rem;
                            quo = (dividend_sign ^ divisor_sign) ? -quo : quo;
                        end
                        result <= {rem, quo};
                        res_valid <= 1;
                        state <= DONE;
                    end
                end

                DONE: begin
                    if (!opn_valid) begin
                        state <= IDLE;
                        res_valid <= 0;
                    end
                end
            endcase
        end
    end

endmodule

