module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [7:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [7:0] rem = a_reg[15:8];
    result = 16'b0;
    odd = 16'b0;
    for (int i = 0;
 i < 16;
 i = i + 1) begin
        reg [7:0] new_rem = {rem[6:0], a_reg[15 - i]};
        if (new_rem >= b_reg) begin
            result[15 - i] = 1'b1;
            rem = new_rem - b_reg;
        end else begin
            result[15 - i] = 1'b0;
            rem = new_rem;
        end
    end
    odd = {8'b0, rem};
end

endmodule

