module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    always @(*) begin
        if (sign_a == sign_b) begin

            c = {sign_a, a_abs + b_abs};
        end else begin

            if (a_abs > b_abs) begin
                c = {sign_a, a_abs - b_abs};
            end else if (b_abs > a_abs) begin
                c = {sign_b, b_abs - a_abs};
            end else begin
                c = 0;
            end
        end
    end

endmodule

