module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'b100;

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        dataOut <= 4'b0;
        EMPTY <= 1'b1;
        FULL <= 1'b0;
    end else if (EN) begin
        reg [2:0] next_SP = SP;

        reg write_enable = 0;
        reg read_enable = 0;

        if (RW == 0) begin 
            if (!FULL) begin
                next_SP = SP - 1;
                stack_mem[SP-1] <= dataIn;
            end
        end else begin 
            if (!EMPTY) begin
                next_SP = SP + 1;
                dataOut <= stack_mem[SP];
            end
        end

        SP <= next_SP;
        EMPTY <= (next_SP == 3'b100);

        FULL <= (next_SP == 3'b000);

    end
end

