module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam IDLE  = 2'b00,
           STATE0 = 2'b01,
           STATE1 = 2'b10,
           STATE2 = 2'b11;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                data_out <= 0;
                state <= (data_in == 0) ? STATE0 : IDLE;
            end
            STATE0: begin
                data_out <= 0;
                state <= (data_in == 1) ? STATE1 : IDLE;
            end
            STATE1: begin
                data_out <= 0;
                state <= (data_in == 0) ? STATE2 : IDLE;
            end
            STATE2: begin
                data_out <= 1;
                state <= IDLE;
            end
            default: begin
                state <= IDLE;
                data_out <= 0;
            end
        endcase
    end
end

endmodule

