        if (!rst_n) begin
            data_lock <= 8'b0;
            has_data <= 1'b0;
            pending_data <= 16'b0;
            valid_pending <= 1'b0;
            valid_out <= 1'b0;
            data_out <= 16'b0;
        end else begin

            valid_out <= 1'b0;

            if (valid_in) begin
                if (has_data) begin

                    pending_data <= {data_lock, data_in};
                    has_data <= 1'b0;
                    valid_pending <= 1'b1;
                end else begin

                    data_lock <= data_in;
                    has_data <= 1'b1;
                end
            end


            if (valid_pending) begin
                valid_out <= 1'b1;
                data_out <= pending_data;
                valid_pending <= 1'b0;
            end
        end
    end

