module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg, divisor_reg;
reg [8:0] SR;

reg [7:0] abs_dividend, abs_divisor;
reg [7:0] neg_divisor;
reg [3:0] cnt;
reg start_cnt;

function [7:0] abs(input [7:0] val);
    abs = val[7] ? (~val + 1) : val;
endfunction

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_reg <= dividend;
            divisor_reg <= divisor;
            abs_dividend <= sign ? abs(dividend) : dividend;
            abs_divisor <= sign ? abs(divisor) : divisor;
            neg_divisor <= -abs_divisor;

            SR <= {abs_dividend, 1'b0} << 1;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end

        if (start_cnt) begin
            if (cnt <= 8) begin

                reg [8:0] temp_remainder = SR;
                reg [7:0] new_remainder;
                reg [7:0] new_quotient;


                new_remainder = temp_remainder[8:1] - neg_divisor;


                if (new_remainder[7] == 1'b0) begin 
                    new_remainder = {new_remainder[7:0], 1'b1};
                end else begin
                    new_remainder = {new_remainder[7:0], 1'b0};
                end

                SR <= new_remainder;
                cnt <= cnt + 1;
            end else begin

                start_cnt <= 0;
                cnt <= 0;

                if (sign) begin

                    if ((dividend_reg[7] ^ divisor_reg[7])) begin
                        SR[7:0] = ~SR[7:0] + 1;

                    end

                    if (dividend_reg[7]) begin
                        SR[16:9] = ~SR[16:9] + 1;

                    end
                end

                result <= {SR[16:9], SR[7:0]};
                res_valid <= 1;
            end
        end

        if (res_valid) begin

            res_valid <= 0;
        end
    end
end

endmodule

