module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result = 0,
    output reg [15:0] odd = 0
);

reg [7:0] a_reg, b_reg;
reg [15:0] quotient;
reg [15:0] remainder;

always @(A or B) begin
    a_reg <= A;
    b_reg <= B;
end

always @(A or B) begin
    quotient = 16'b0;
    remainder = 16'b0;

    for (int i = 15;
 i >= 0;
 i--) begin
        remainder = remainder << 1;
        remainder[0] = a_reg[i];

        if (remainder >= {8'b0, b_reg}) begin
            remainder = remainder - {8'b0, b_reg};
            quotient[i] = 1;
        end else begin
            quotient[i] = 0;
        end
    end

    odd = {8'b0, remainder[7:0]};
    result = quotient;
end

endmodule

