module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input C_in,
    output [15:0] S,
    output PG,
    output GG,
    output C_out
);
    wire [15:0] G, P;
    assign G = A & B;
    assign P = A ^ B;

    wire [15:0] product;
    assign product[15] = P[15];
    genvar j;
    generate
        for (j = 14;
 j >= 0;
 j = j - 1) begin : product_gen
            assign product[j] = P[j] & product[j+1];
        end
    endgenerate

    assign GG = | (G & product);
    assign PG = &P;

    wire [16:0] C;
    assign C[0] = C_in;
    genvar i;
    generate
        for (i = 0;
 i < 16;
 i = i + 1) begin : carry_gen
            assign C[i+1] = G[i] | (P[i] & C[i]);
        end
    endgenerate

    assign C_out = GG | (PG & C_in);
    assign S = P ^ C[15:0];
endmodule

