module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] a_abs, b_abs;
reg [N-1:0] diff;
reg sign;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        c = a + b;
    end else begin

        a_abs = a[N-1] ? (~a + 1) : a;
        b_abs = b[N-1] ? (~b + 1) : b;
        if (a_abs > b_abs) begin
            diff = a_abs - b_abs;
            sign = a[N-1];
        end else if (a_abs < b_abs) begin
            diff = b_abs - a_abs;
            sign = b[N-1];
        end else begin
            diff = 0;
            sign = 0;
        end

        if (sign) begin
            c = ~{1'b0, diff} + 1;
        end else begin
            c = {1'b0, diff};
        end
    end
end

endmodule

