module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, sum_exp;
    reg [23:0] a_mantissa, b_mantissa, product_mantissa;
    reg [49:0] product;
    reg [22:0] round_mantissa;
    reg guard_bit, round_bit, sticky_bit;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};

                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a_exponent == 8'hFF && |a[22:0]) || 
                        (b_exponent == 8'hFF && |b[22:0])) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                    end else if ((a_exponent == 8'hFF) || (b_exponent == 8'hFF)) begin
                        if ((a_exponent == 0 && |a[22:0]) || 
                            (b_exponent == 0 && |b[22:0])) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        sum_exp <= a_exponent + b_exponent - 8'd127;
                        counter <= 1;
                    end
                end

                1: begin

                    if (product[47]) begin
                        product_mantissa <= product[47:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky_bit <= |product[21:0];
                        sum_exp <= sum_exp + 8'd1;
                    end else begin
                        product_mantissa <= product[46:23];
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky_bit <= |product[20:0];
                    end
                    counter <= 2;
                end

                2: begin

                    if (guard_bit) begin
                        if (round_bit || sticky_bit) begin
                            round_mantissa <= product_mantissa + 1;
                            if (product_mantissa == 23'h7FFFFF) begin 
                                product_mantissa <= 23'h0;
                                sum_exp <= sum_exp + 8'd1;
                            end else begin
                                round_mantissa <= product_mantissa + 1;
                            end
                        end else begin
                            round_mantissa <= product_mantissa;
                        end
                    end else begin
                        round_mantissa <= product_mantissa;
                    end
                    counter <= 3;
                end

                3: begin

                    if (sum_exp >= 255) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else if (sum_exp <= 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                    end else begin
                        z <= {a_sign ^ b_sign, sum_exp, round_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

