    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;

reg [ADDR_WIDTH:0] wptr, rptr;

reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;
reg [PTR_WIDTH-1:0] wptr_sync1, wptr_sync2;

reg [PTR_WIDTH-1:0] rptr_sync1, rptr_sync2;



dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(wenc),
    .waddr(wptr[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(renc),
    .raddr(rptr[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
        rptr_sync1 <= 0;
        rptr_sync2 <= 0;
    end else begin
        rptr_sync1 <= rptr;
        rptr_sync2 <= rptr_sync1;
        if (wenc) begin
            wptr <= binary_to_gray(wptr + 1);
        end
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
        wptr_sync1 <= 0;
        wptr_sync2 <= 0;
    end else begin
        wptr_sync1 <= wptr;
        wptr_sync2 <= wptr_sync1;
        if (renc) begin
            rptr <= binary_to_gray(rptr + 1);
        end
    end
end


function [ADDR_WIDTH-1:0] gray_to_binary(input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] binary;
    integer i;
    begin
        binary[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            binary[i] = binary[i+1] ^ gray[i];
        gray_to_binary = binary[ADDR_WIDTH-1:0];
    end
endfunction


function [PTR_WIDTH-1:0] binary_to_gray(input [PTR_WIDTH-1:0] binary);
    binary_to_gray = (binary >> 1) ^ binary;
endfunction


