module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

reg [1:0] state;

localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
    end
    else begin
        case (state)
            S0: state <= (data_in) ? S1 : S0;
            S1: state <= (!data_in) ? S2 : S1;
            S2: state <= (!data_in) ? S0 : S1;
            default: state <= S0;
        endcase
    end
end

assign data_out = (state == S2) && (!data_in);

endmodule

