module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output tri flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    assign zero = (r == 32'b0);
    assign negative = r[31];

    reg flag_reg;

    always @(*) begin
        case (aluc)
            SLT: flag_reg = ($signed(a) < $signed(b));
            SLTU: flag_reg = (a < b);
            default: flag_reg = 1'bz;
        endcase
    end

    assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;

    always @(*) begin
        carry = 0;
        overflow = 0;
        r = 32'bz;

        case (aluc)
            ADD: {carry, r} = {1'b0, a} + {1'b0, b};
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            ADDU: {carry, r} = {1'b0, a} + {1'b0, b};
            SUB: {carry, r} = {1'b0, a} - {1'b0, b};
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            SUBU: {carry, r} = {1'b0, a} - {1'b0, b};
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            SLTU: r = (a < b) ? 32'd1 : 32'd0;
            SLL: r = a << b[4:0];
            SRL: r = a >> b[4:0];
            SRA: r = $signed(a) >>> b[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = $signed(b) >>> a[4:0];
            LUI: r = {a[15:0], 16'b0};
            default: r = 32'bz;
        endcase
    end

endmodule

