module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [7:0] NEG_DIVISOR;
    reg [15:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg original_dividend_sign;
    reg original_divisor_sign;
    reg [7:0] final_quotient;
    reg [7:0] final_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            NEG_DIVISOR <= 0;
            original_dividend_sign <= 0;
            original_divisor_sign <= 0;
            final_quotient <= 0;
            final_remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                original_dividend_sign <= dividend[7];
                original_divisor_sign <= divisor[7];
                if (sign) begin
                    dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                    divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                end else begin
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                end

                SR <= {dividend_abs, 8'b0} << 1;
                NEG_DIVISOR <= ~divisor_abs + 1;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= NEG_DIVISOR) begin
                        SR[15:8] <= SR[15:8] - NEG_DIVISOR[7:0];
                        SR <= {SR[14:0], 1'b1};
                    end else begin
                        SR <= {SR[14:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 0;
                end
            end


            if (sign && res_valid) begin
                if (original_dividend_sign ^ original_divisor_sign) begin
                    final_quotient <= ~SR[7:0] + 1;
                end else begin
                    final_quotient <= SR[7:0];
                end

                if (original_dividend_sign) begin
                    final_remainder <= ~SR[15:8] + 1;
                end else begin
                    final_remainder <= SR[15:8];
                end
            end else begin
                final_quotient <= SR[7:0];
                final_remainder <= SR[15:8];
            end


            if (cnt == 8) begin
                result <= {final_remainder, final_quotient};
                res_valid <= 1;
            end else begin
                res_valid <= 0;
            end
        end
    end
endmodule

