        for (i = 0;
 i < 16;
 i = i + 1) begin

            remainder = (remainder << 1) | (a_reg >> (15 - i)) & 1;


            if (remainder >= {8'b0, b_reg}) begin
                quotient[15 - i] = 1;
                remainder = remainder - {8'b0, b_reg};
            end else begin
                quotient[15 - i] = 0;
            end
        end


        result = quotient;
        odd = remainder;
    end

