module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a + b;
        end else begin

            reg [N-2:0] abs_a, abs_b;
            abs_a = a[N-1] ? (~a[N-2:0] + 1) : a[N-2:0];
            abs_b = b[N-1] ? (~b[N-2:0] + 1) : b[N-2:0];

            if (abs_a > abs_b) begin
                res = {1'b0, (abs_a - abs_b)};
            end else if (abs_b > abs_a) begin
                res = {1'b1, (abs_b - abs_a)};
            end else begin
                res = 0;
            end
        end
    end

    assign c = res;

endmodule

