module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    localparam IDLE    = 2'b00;
    localparam S1_RED  = 2'b01;
    localparam S2_YELLOW = 2'b10;
    localparam S3_GREEN = 2'b11;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                IDLE: begin
                    state <= S1_RED;
                end
                S1_RED: begin
                    if (cnt == 0) begin
                        state <= S3_GREEN;
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                S3_GREEN: begin
                    if (cnt == 0) begin
                        state <= S2_YELLOW;
                        cnt <= 5;
                    end else begin

                        if (pass_request && (cnt > 10))
                            cnt <= 10;
                        else
                            cnt <= cnt - 1;
                    end
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                end
                S2_YELLOW: begin
                    if (cnt == 0) begin
                        state <= S1_RED;
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                end
                default: state <= IDLE;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            case (state)
                IDLE: cnt <= 10;
                S1_RED: cnt <= 10;
                S3_GREEN: cnt <= 60;
                S2_YELLOW: cnt <= 5;
                default: cnt <= cnt;
            endcase
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

