module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [8:0] remainder;
    reg [7:0] quotient;
    reg [8:0] neg_divisor;
    reg [3:0] cnt;
    reg [1:0] state;

    localparam IDLE = 0;
    localparam BUSY = 1;
    localparam DONE = 2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            state <= IDLE;
            remainder <= 0;
            quotient <= 0;
            cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            neg_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin

                        if (sign) begin
                            dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                            divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                        end else begin
                            dividend_abs <= dividend;
                            divisor_abs <= divisor;
                        end

                        remainder <= {dividend_abs, 1'b0};
                        quotient <= 0;
                        cnt <= 1;
                        state <= BUSY;
                    end
                end
                BUSY: begin
                    if (cnt == 8) begin
                        state <= DONE;
                    end else begin

                        if (remainder >= {1'b0, neg_divisor}) begin
                            remainder <= remainder - {1'b0, neg_divisor};
                            quotient <= {quotient[6:0], 1'b1};
                        end else begin
                            remainder <= remainder;
                            quotient <= {quotient[6:0], 1'b0};
                        end
                        cnt <= cnt + 1;
                    end
                end
                DONE: begin

                    if (sign) begin

                        if (dividend_abs[7] ^ divisor_abs[7]) begin
                            quotient <= ~quotient + 1;
                        end

                        if (dividend_abs[7]) begin
                            remainder <= {1'b0, ~remainder[7:0] + 1};
                        end
                    end

                    result <= {remainder[7:0], quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end
            endcase

            if (state == IDLE && opn_valid) begin
                neg_divisor <= {1'b0, divisor_abs} + 1;
            end
        end
    end

endmodule

