    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            adda_reg <= 64'b0;
            addb_reg <= 64'b0;
            en_pipe[0] <= 0;
        end else if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
            en_pipe[0] <= 1;
        end else begin
            en_pipe[0] <= 0;
        end
    end

    wire [31:0] adda_low = adda_reg[31:0];
    wire [31:0] addb_low = addb_reg[31:0];
    wire [31:0] sum_low;
    wire carry_out_low;

    assign {carry_out_low, sum_low} = adda_low + addb_low;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_low_reg <= 32'b0;
            carry_reg <= 0;
            en_pipe[1] <= 0;
        end else if (en_pipe[0]) begin
            sum_low_reg <= sum_low;
            carry_reg <= carry_out_low;
            en_pipe[1] <= 1;
