            en_pipe[2] <= 1;
        end else begin
            sum_high_reg <= sum_high_reg;
            en_pipe[2] <= 0;
        end
    end


    wire [64:0] combined_result = {carry_out_high, sum_high_reg, sum_low_reg};


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 65'b0;
        end else if (en_pipe[2]) begin
            result <= combined_result;
        end else begin
            result <= result;
        end
    end

    assign o_en = en_pipe[2];

