module fixed_point_adder #(
    parameter N = 8,  
    parameter Q = 4    
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg a_sign, b_sign;
    reg [N-1:0] mag_a, mag_b;
    reg [N:0] sum_mag;
    reg [N-1:0] res;
    reg res_sign;
    reg [N-1:0] res_magnitude;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            mag_a = a_sign ? (~a + 1) : a;
            mag_b = b_sign ? (~b + 1) : b;
            sum_mag = mag_a + mag_b;

            if (sum_mag > (2**(N-1) - 1)) begin

                res = {a_sign, {(N-1){1'b0}}};
            end else begin

                res = {a_sign, sum_mag[N-2:0]};
            end
        end else begin

            mag_a = a_sign ? (~a + 1) : a;
            mag_b = b_sign ? (~b + 1) : b;

            if (mag_a > mag_b) begin
                res_magnitude = mag_a - mag_b;
                res_sign = 0;
            end else if (mag_b > mag_a) begin
                res_magnitude = mag_b - mag_a;
                res_sign = 1;
            end else begin
                res_magnitude = 0;
                res_sign = 0;
            end

            res = {res_sign, res_magnitude[N-2:0]};
        end

        c = res;
    end

endmodule

