module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [47:0] product_shifted;
    reg [9:0] exponent;
    reg guard_bit, round_bit, sticky_bit;


    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 1;
                end

                1: begin

                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};

                        end else if ((a_exponent == 8'hFF && a_mantissa == 0) || 
                                   (b_exponent == 8'hFF && b_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};

                        end else begin
                            z <= {a_sign ^ b_sign, a_exponent == 8'hFF ? a_exponent : b_exponent, 23'h0};
                        end
                        counter <= 0;
                    end else if (a_mantissa == 0 || b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 0;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 2;
                    end
                end

                2: begin

                    integer i;
                    reg [5:0] leading_zeros;
                    leading_zeros = 0;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i] == 1'b1) begin
                            leading_zeros = 47 - i;
                            break;
                        end
                    end
                    product_shifted <= product << leading_zeros;
                    exponent <= exponent - leading_zeros + 10'd127;
                    counter <= 3;
                end

                3: begin


                    guard_bit <= product_shifted[23];
                    round_bit <= product_shifted[22];
                    sticky_bit <= |product_shifted[21:0];

                    if (guard_bit && (round_bit || sticky_bit)) begin
                        if (product_shifted[47]) begin
                            product_shifted[47:24] <= product_shifted[47:24] + 1;
                        end else begin
                            product_shifted[47:24] <= {1'b1, product_shifted[46:24]};
                        end
                    end

                    if (product_shifted[47:24] > 24'hFFFFFF) begin
                        product_shifted[47:24] <= product_shifted[47:24] + 1;
                        exponent <= exponent + 1;
                    end
                    counter <= 4;
                end

                4: begin

                    if (exponent >= 10'h100) begin 
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                    end else if (exponent <= 0) begin 
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent[7:0], product_shifted[46:24]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end
