module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [1:0] state;
    reg [7:0] original_sign;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [7:0] neg_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;

    localparam IDLE = 0;
    localparam SETUP = 1;
    localparam DIVIDE = 2;
    localparam ADJUST = 3;
    localparam DONE = 4;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin
                        dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                        original_sign <= {dividend[7], divisor[7]};
                        state <= SETUP;
                    end
                end
                SETUP: begin
                    SR <= {8'b0, dividend_abs} << 1;
                    neg_divisor <= -divisor_abs;
                    cnt <= 0;
                    state <= DIVIDE;
                end
                DIVIDE: begin
                    if (cnt < 8) begin
                        if (SR[15:8] >= neg_divisor) begin
                            SR[15:8] <= SR[15:8] - neg_divisor;
                            SR <= {SR[15:8] - neg_divisor, SR[7:0], 1'b1} << 1;
                        end else begin
                            SR <= SR << 1;
                        end
                        cnt <= cnt + 1;
                    end else begin
                        state <= ADJUST;
                    end
                end
                ADJUST: begin
                    reg [7:0] quotient = SR[7:0];
                    reg [7:0] remainder = SR[15:8];
                    reg [7:0] final_quotient;
                    reg [7:0] final_remainder;

                    if (original_sign[0]) begin
                        final_remainder = -remainder;
                    end else begin
                        final_remainder = remainder;
                    end

                    if (original_sign[0] ^ original_sign[1]) begin
                        final_quotient = -quotient;
                    end else begin
                        final_quotient = quotient;
                    end

                    result <= {final_remainder, final_quotient};
                    state <= DONE;
                end
                DONE: begin
                    res_valid <= 1;
                    if (!opn_valid) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

