module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output C_out
);
    wire [16:1] G, P;
    wire [16:0] C;


    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_gp
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] ^ B[i];
        end
    endgenerate


    assign C[0] = C_in;
    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_carry
            assign C[i] = G[i] | (P[i] & C[i-1]);
        end
    endgenerate


    assign S = P ^ C[16:1];
    assign C_out = C[16];

