module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        case ({a[N-1], b[N-1]})
            2'b00: res = a - b;

            2'b01: begin       
                reg [N-1:0] abs_b = -b;
                if (a >= abs_b) begin
                    res = a - abs_b;
                end else begin
                    res = b - a;
                    res[N-1] = 1;

                end
            end
            2'b10: begin       
                reg [N-1:0] abs_a = -a;
                if (abs_a <= b) begin
                    res = abs_a - b;
                end else begin
                    res = a - b;
                    res[N-1] = 1;

                end
            end
            2'b11: begin       
                reg [N-1:0] abs_a = -a, abs_b = -b;
                res = -(abs_a + abs_b);
            end
            default: res = 0;
        endcase


        if (res == 0) res[N-1] = 0;
    end

    assign c = res;

endmodule

