module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg a_sign, b_sign;
    reg [47:0] product;
    reg [9:0] z_exponent;
    reg z_sign;
    reg guard_bit, round_bit, sticky;
    reg [22:0] rounded_mantissa;
    reg [9:0] rounded_exponent;


    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin
                    counter <= 1;
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];
                    a_sign <= a[31];
                    b_sign <= b[31];
                end

                1: begin

                    if (a_exponent == 8'hFF && a_mantissa != 0 || 
                        b_exponent == 8'hFF && b_mantissa != 0) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h400001};
                        counter <= 0;
                    end else if ((a_exponent == 8'hFF && a_mantissa == 0) || 
                                (b_exponent == 8'hFF && b_mantissa == 0)) begin

                        if ((a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h400000};
                        end
                        counter <= 0;
                    end else if ((a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0)) begin

                        z <= {a_sign ^ b_sign, 23'b0, 31'b0};
                        counter <= 0;
                    end else begin

                        counter <= 2;

                        product <= (a_exponent[0] ? {1'b1, a_mantissa} : {1'b0, a_mantissa}) * 
                                   (b_exponent[0] ? {1'b1, b_mantissa} : {1'b0, b_mantissa});

                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        z_sign <= a_sign ^ b_sign;
                    end
                end

                2: begin

                    integer i;
                    reg [47:0] temp = product;
                    for (i = 47;
 i >= 0;
 i = i - 1)
                        if (temp[i]) begin
                            product <= temp << (47 - i);
                            z_exponent <= z_exponent - (47 - i);
                            break;
                        end
                    counter <= 3;
                end

                3: begin

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];

                    rounded_mantissa <= product[47:24];
                    if (guard_bit && (round_bit || sticky)) begin
                        rounded_mantissa <= rounded_mantissa + 1;
                    end

                    if (rounded_mantissa[23]) begin
                        rounded_exponent <= z_exponent + 1;
                        rounded_mantissa <= 0;
                    end else begin
                        rounded_exponent <= z_exponent;
                    end
                    counter <= 4;
                end

                4: begin

                    if (rounded_exponent > 9'h0FF) begin

                        z <= {z_sign, 8'hFF, 23'b0};
                    end else if (rounded_exponent < 9'h1) begin

                        z <= {z_sign, 31'b0};
                    end else begin

                        z <= {z_sign, rounded_exponent[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

