        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[3:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[3:0]),
        .rdata(rdata)
    );


    reg [4:0] waddr_bin;
    reg [4:0] waddr_gray;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            waddr_gray <= 0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
            waddr_gray <= (waddr_bin + 1) ^ ((waddr_bin + 1) >> 1);
        end
    end


    reg [4:0] raddr_bin;
    reg [4:0] raddr_gray;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            raddr_gray <= 0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
            raddr_gray <= (raddr_bin + 1) ^ ((raddr_bin + 1) >> 1);
