module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 3'b100);

assign FULL = (SP == 3'b000);


always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        dataOut <= 4'b0;
    end
    else if (EN) begin
        if (RW) begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
        else begin 
            if (!FULL) begin
                SP <= SP - 1;
                stack_mem[SP] <= dataIn;
            end
        end
    end
end

endmodule

