module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

    reg [1:0] state;
    reg [7:0] cnt;
    reg pass_request_prev;

    localparam idle     = 2'b00,
               s1_red   = 2'b01,
               s2_yellow= 2'b10,
               s3_green = 2'b11;

    wire pass_request_edge = pass_request && !pass_request_prev;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
            pass_request_prev <= 0;
        end else begin
            pass_request_prev <= pass_request;
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 10;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request_edge && cnt > 10)
                        cnt <= 10;
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 5;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end

    assign red = (state == s1_red);
    assign yellow = (state == s2_yellow);
    assign green = (state == s3_green);

    always @(*) begin
        clock = cnt;
    end

endmodule

