module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result
);

    reg [7:0] saved_dividend, saved_divisor;
    reg [3:0] cnt;
    reg [16:0] SR;

    reg negate_quotient, negate_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            negate_quotient <= 0;
            negate_remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    saved_dividend <= dividend[7] ? -dividend : dividend;
                    saved_divisor <= divisor[7] ? -divisor : divisor;
                    negate_quotient <= (dividend[7] != divisor[7]);
                    negate_remainder <= divisor[7];
                end else begin
                    saved_dividend <= dividend;
                    saved_divisor <= divisor;
                    negate_quotient <= 0;
                    negate_remainder <= 0;
                end


                SR <= {8'b0, saved_dividend} << 1;
                cnt <= 1;
            end else if (res_valid) begin
                res_valid <= 0;
            end

            if (cnt >= 1 && cnt <= 8) begin

                if (SR[16:8] >= saved_divisor) begin
                    SR <= {SR[16:8] - saved_divisor, SR[7:0], 1'b1};
                end else begin
                    SR <= {SR[16:8], SR[7:0], 1'b0};
                end


                cnt <= cnt + 1;
            end

            if (cnt == 8) begin

                result <= {SR[16:1], SR[0]};
                if (negate_quotient)
                    result[7:0] <= -result[7:0];
                if (negate_remainder)
                    result[15:8] <= -result[15:8];
                res_valid <= 1;
                cnt <= 0;
            end
        end
    end

endmodule

