module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [3:0] eq;

    assign eq[3] = (A[3] == B[3]);
    assign eq[2] = (A[2] == B[2]);
    assign eq[1] = (A[1] == B[1]);
    assign eq[0] = (A[0] == B[0]);

    assign A_equal = &eq;

    wire term_greater_3, term_greater_2, term_greater_1, term_greater_0;
    assign term_greater_3 = A[3] & ~B[3];
    assign term_greater_2 = (A[2] & ~B[2]) & eq[3];
    assign term_greater_1 = (A[1] & ~B[1]) & eq[3] & eq[2];
    assign term_greater_0 = (A[0] & ~B[0]) & eq[3] & eq[2] & eq[1];

    assign A_greater = term_greater_3 | term_greater_2 | term_greater_1 | term_greater_0;

    wire term_less_3, term_less_2, term_less_1, term_less_0;
    assign term_less_3 = ~A[3] & B[3];
    assign term_less_2 = (~A[2] & B[2]) & eq[3];
    assign term_less_1 = (~A[1] & B[1]) & eq[3] & eq[2];
    assign term_less_0 = (~A[0] & B[0]) & eq[3] & eq[2] & eq[1];

    assign A_less = term_less_3 | term_less_2 | term_less_1 | term_less_0;

endmodule

