        if (!rst_n) begin
            i <= 5'b0;
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
            done <= 1'b0;
        end else begin
            reg [4:0] next_i;


            if (!start) begin
                next_i = 5'b0;
            end else if (i < 5'b10001) begin 
                next_i = i + 1;
            end else begin
                next_i = i;
            end


            i <= next_i;
            if (next_i == 5'b10000) begin 
                done <= 1'b1;
            end else if (next_i == 5'b10001) begin 
                done <= 1'b0;
            end else begin
                done <= done;
            end


            if (start) begin
                if (i == 5'b0) begin
                    areg <= ain;
                    breg <= bin;
                    yout_r <= 32'b0;
                end else if (next_i >= 5'b1 && next_i <= 5'b10000) begin
                    if (areg[next_i - 1]) begin
                        yout_r <= yout_r + (breg << (next_i - 1));
                    end
                end
            end


            yout <= yout_r;
        end
    end

