module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    wire [N:0] sum_abs = {1'b0, a_abs} + {1'b0, b_abs};
    wire overflow_add = (sum_abs > (2**(N-1) - 1));

    wire [N-1:0] res_abs_add = overflow_add ? (2**(N-1) - 1) : sum_abs[N-1:0];
    wire [N-1:0] res_sign_add = sign_a;

    wire [N-1:0] sub_result = (a_abs > b_abs) ? (a_abs - b_abs) : (b_abs - a_abs);
    wire [N-1:0] sub_sign = (a_abs > b_abs) ? sign_a : (b_abs > a_abs) ? sign_b : 0;

    assign c = same_sign ? {res_sign_add, res_abs_add} : {sub_sign, sub_result};

endmodule

