    z_sign = a_sign ^ b_sign;
end


always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                a_exponent <= a[30:23];
                a_mant <= {1'b1, a[22:0]};


                b_sign <= b[31];
                b_exponent <= b[30:23];
                b_mant <= {1'b1, b[22:0]};



                if ((a_exponent == 8'hFF && |a[22:0]) || (b_exponent == 8'hFF && |b[22:0])) begin
                    if ((a_exponent == 8'hFF && b_exponent == 8'hFF)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, a[22:0] | b[22:0]};
                    end else if (a_exponent == 8'hFF) begin

                        z <= {a_sign, 8'hFF, a[22:0]};
                    end else begin

                        z <= {b_sign, 8'hFF, b[22:0]};
                    end
                    counter <= 0;
                end else if (a_exponent == 8'hFF) begin

                    if (b_exponent == 0 && b_mant == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end
                    counter <= 0;
                end else if (b_exponent == 8'hFF) begin

                    if (a_exponent == 0 && a_mant == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end
                    counter <= 0;
                end else if (a_exponent == 0 && a_mant == 0 && b_exponent == 0 && b_mant == 0) begin

                    z <= {z_sign, 31'h0};
                    counter <= 0;
                end else if (a_exponent == 0 && a_mant == 0) begin

                    z <= {z_sign, 31'h0};
                    counter <= 0;
                end else if (b_exponent == 0 && b_mant == 0) begin

                    z <= {z_sign, 31'h0};
                    counter <= 0;
                end else begin

                    product <= a_mant * b_mant;
                    counter <= 1;
                end
            end

            1: begin

                if (product[47:46] >= 2) begin
                    product_shifted <= product >> 1;
                    exponent_final <= a_exponent + b_exponent - 127 + 1;
                end else begin
                    product_shifted <= product;
                    exponent_final <= a_exponent + b_exponent - 127;
                end
                counter <= 2;
            end

            2: begin

                if (product_shifted[47]) begin
                    mant_rounded <= product_shifted[45:23];
                    guard <= product_shifted[22];
                    round_bit <= product_shifted[21];
                    sticky <= |product_shifted[20:0];
                end else begin
                    mant_rounded <= product_shifted[46:24];
                    guard <= product_shifted[23];
                    round_bit <= product_shifted[22];
                    sticky <= |product_shifted[21:0];
