                if (guard && (round_bit || sticky) || (guard && !round_bit && !sticky && mant_rounded[0])) begin
                    if (mant_rounded == 23'h7FFFFF) begin
                        mant_rounded <= 23'h0;
                        exponent_final <= exponent_final + 1;
                    end else begin
                        mant_rounded <= mant_rounded + 1;
