                end
                counter <= 3;
            end

            3: begin

                if (exponent_final >= 255) begin
                    z <= {z_sign, 8'hFF, 23'h0};

                end else if (exponent_final <= 0) begin
                    z <= {z_sign, 31'h0};

                end else begin
                    z <= {z_sign, exponent_final[7:0], mant_rounded};
                end
                counter <= 0;
            end

            default: counter <= 0;
        endcase
    end
end

