    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg rempty,
    output reg wfull,
    input rclk,
    input rrstn,
    input rinc,
    output reg [WIDTH-1:0] rdata
);

localparam ADDRSIZE = $clog2(DEPTH);


reg [ADDRSIZE-1:0] waddr_bin, waddr_gray;
reg [ADDRSIZE-1:0] wptr_sync0, wptr_sync;


reg [ADDRSIZE-1:0] raddr_bin, raddr_gray;
reg [ADDRSIZE-1:0] rptr_sync0, rptr_sync;


