dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
    .wclk(wclk),
    .wen(wen),
    .waddr(waddr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .ren(ren),
    .raddr(raddr_bin),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        waddr_gray <= 0;
        {wptr_sync, wptr_sync0} <= 0;
    end else if (wen && !wfull) begin
        waddr_bin <= waddr_bin + 1;
        waddr_gray <= bin2gray(waddr_bin + 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        raddr_gray <= 0;
        {rptr_sync, rptr_sync0} <= 0;
    end else if (ren && !rempty) begin
        raddr_bin <= raddr_bin + 1;
        raddr_gray <= bin2gray(raddr_bin + 1);
    end
end


function [ADDRSIZE-1:0] gray2bin;
    input [ADDRSIZE-1:0] gray;
    integer i;
    begin
        gray2bin[ADDRSIZE-1] = gray[ADDRSIZE-1];
        for (i = ADDRSIZE-2;
 i >= 0;
 i = i - 1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction


function [ADDRSIZE-1:0] bin2gray;
    input [ADDRSIZE-1:0] bin;
    begin
        bin2gray = bin ^ (bin >> 1);
    end
endfunction


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        wfull <= 0;
    else begin
        reg [ADDRSIZE-1:0] rptr_bin = gray2bin(rptr_sync);
        wfull <= (waddr_gray == bin2gray(rptr_bin + 1));
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        rempty <= 1;
    else
        rempty <= (raddr_bin == gray2bin(wptr_sync));
end


assign wen = winc && !wfull;
assign ren = rinc && !rempty;

endmodule

