module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle     = 2'b00,
          s1_red   = 2'b01,
          s2_yellow= 2'b10,
          s3_green = 2'b11;


reg [1:0] state, next_state;


reg [7:0] cnt;


reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= idle;
    else state <= next_state;
end


always @(*) begin
    next_state = state;
    case (state)
        idle:    next_state = s1_red;
        s1_red:  next_state = (cnt == 0) ? s3_green : s1_red;
        s3_green:next_state = (cnt == 0) ? s2_yellow : s3_green;
        s2_yellow:next_state = (cnt == 0) ? s1_red : s2_yellow;
        default: next_state = idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 8'd3;
    else begin
        case (next_state)
            s1_red:   cnt <= 8'd3;
            s2_yellow:cnt <= 8'd3;
            s3_green: cnt <= 8'd3;
            default: begin
                if (pass_request && (state == s3_green)) begin
                    if (cnt > 10) cnt <= 10;
                    else cnt <= cnt;
                end
                else cnt <= cnt - 1;
            end
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end
    else begin
        p_red <= (next_state == s1_red);
        p_yellow <= (next_state == s2_yellow);
        p_green <= (next_state == s3_green);
    end
end


always @(*) begin
    red = p_red;
    yellow = p_yellow;
    green = p_green;
    clock = cnt;
end

endmodule

