module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result = 0
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam CALCULATING = 2'b01;
    localparam DONE = 2'b10;

    reg [7:0] abs_dividend, abs_divisor;
    reg q_sign, rem_sign;
    reg [15:0] shift_reg;
    reg [3:0] cnt;
    reg [7:0] divisor_neg;
    reg [7:0] q_temp, rem_temp;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            shift_reg <= 0;
            cnt <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                            q_sign <= dividend[7] ^ divisor[7];
                            rem_sign <= dividend[7];
                        end else begin
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                            q_sign <= 0;
                            rem_sign <= 0;
                        end

                        shift_reg <= {8'b0, abs_dividend};
                        divisor_neg <= ~abs_divisor + 1;
                        cnt <= 0;
                        state <= CALCULATING;
                    end
                end
                CALCULATING: begin
                    if (cnt < 8) begin

                        shift_reg <= shift_reg << 1;

                        if (shift_reg[15:8] >= abs_divisor) begin
                            shift_reg[15:8] <= shift_reg[15:8] - abs_divisor;
                            shift_reg[0] <= 1;
                        end
                        cnt <= cnt + 1;
                    end else begin

                        q_temp <= shift_reg[7:0];
                        rem_temp <= shift_reg[15:8];

                        if (sign) begin
                            q_temp <= q_sign ? -shift_reg[7:0] : shift_reg[7:0];
                            rem_temp <= rem_sign ? -shift_reg[15:8] : shift_reg[15:8];
                        end
                        result <= {rem_temp, q_temp};
                        res_valid <= 1;
                        state <= DONE;
                    end
                end
                DONE: begin
                    if (opn_valid) begin
                        state <= IDLE;
                        res_valid <= 0;
                    end
                end
            endcase
        end
    end

endmodule

