reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [8:0] remainder;

    reg [15:0] quotient;
    integer i;

    remainder = 9'b0;
    quotient = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = {remainder[7:0], a_reg[i]};
        if (remainder >= {1'b0, b_reg}) begin
            remainder = remainder - {1'b0, b_reg};
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = {8'b0, remainder[7:0]};
end

endmodule

