module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard_bit, round_bit, sticky;


wire a_is_zero = (a[30:23] == 8'd0) && (a[22:0] == 23'd0);
wire b_is_zero = (b[30:23] == 8'd0) && (b[22:0] == 23'd0);
wire a_is_inf = (a[30:23] == 8'hff) && (a[22:0] == 23'd0);
wire b_is_inf = (b[30:23] == 8'hff) && (b[22:0] == 23'd0);
wire a_is_nan = (a[30:23] == 8'hff) && (a[22:0] != 23'd0);
wire b_is_nan = (b[30:23] == 8'hff) && (b[22:0] != 23'd0);


always @(posedge clk) begin
    if (rst) begin
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        counter <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};
                a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                if (a_is_nan || b_is_nan) begin
                    z <= {1'b0, 8'hff, 23'h100000};
                    counter <= 0;
                end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                    z <= {1'b0, 8'hff, 23'h100000};
                    counter <= 0;
                end else if (a_is_inf || b_is_inf) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    counter <= 0;
                end else if (a_is_zero || b_is_zero) begin
                    z <= {a_sign ^ b_sign, 31'd0};
                    counter <= 0;
                end else begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 1;
                end
            end

            1: begin

                if (product[47]) begin
                    product <= product >> 1;
                    z_exponent <= a_exponent + b_exponent - 9'd255;
                end else begin
                    z_exponent <= a_exponent + b_exponent - 9'd254;
                end
                counter <= 2;
            end

            2: begin

                guard_bit <= product[22];
                round_bit <= product[21];
                sticky <= |product[20:0];
