module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

wire [1:0] addr;
assign addr = SP[1:0];

assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

reg [3:0] dataOut_reg;

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 4;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end
        else begin
            if (!RW) begin 
                if (!FULL) begin
                    stack_mem[addr] <= dataIn;
                    SP <= SP - 1;
                end
            end
            else begin 
                if (!EMPTY) begin
                    dataOut_reg <= stack_mem[addr];
                    SP <= SP + 1;
                end
            end
        end
    end
end

assign dataOut = dataOut_reg;

endmodule

