module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


localparam IDLE  = 2'b00;
localparam FALL  = 2'b01;
localparam RISE  = 2'b10;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 0) begin
                    state <= FALL;
                end
                data_out <= 0;
            end
            FALL: begin
                if (data_in == 1) begin
                    state <= RISE;
                end else begin
                    state <= IDLE;
                end
                data_out <= 0;
            end
            RISE: begin
                if (data_in == 0) begin
                    data_out <= 1;
                    state <= IDLE;
                end else begin
                    data_out <= 0;
                    state <= IDLE;
                end
            end
            default: begin
                state <= IDLE;
                data_out <= 0;
            end
        endcase
    end
end

endmodule

