    if (!rst_n) begin
        state <= IDLE;
        cnt <= 8'd10;
        p_red <= 1;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        case (state)
            IDLE: begin
                state <= S1_RED;
                cnt <= 8'd10;
                p_red <= 1;
                p_yellow <= 0;
                p_green <= 0;
            end
            S1_RED: begin
                if (cnt == 0) begin
