    input wire rst_n,
    input wire valid_in,
    input wire [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg state;
    reg [7:0] first_data;

    localparam IDLE = 0;
    localparam HAVE_FIRST = 1;

