        if (!rst_n) begin
            state <= IDLE;
            first_data <= 8'b0;
            data_out <= 16'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;

            case (state)
                IDLE: begin
                    if (valid_in) begin
                        first_data <= data_in;
                        state <= HAVE_FIRST;
                    end
                end
                HAVE_FIRST: begin
                    if (valid_in) begin
                        data_out <= {first_data, data_in};
                        valid_out <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

