module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] SR;

    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg start_cnt;

    wire [7:0] remainder = SR[7:0];
    wire [7:0] quotient = SR[15:8];


    always @(*) begin
        if (sign) begin
            abs_dividend = dividend[7] ? -dividend : dividend;
            abs_divisor = divisor[7] ? -divisor : divisor;
        end else begin
            abs_dividend = dividend;
            abs_divisor = divisor;
        end
        NEG_DIVISOR = -abs_divisor;
    end

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                SR <= {abs_dividend, 1'b0};

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin
                    if (cnt == 8) begin

                        if (SR[8:1] >= abs_divisor) begin
                            SR[8:1] <= SR[8:1] - abs_divisor;
                            SR[0] <= 1;
                        end else begin
                            SR[0] <= 0;
                        end
                        start_cnt <= 0;
                        cnt <= 0;
                        res_valid <= 1;
                    end else begin

                        reg [8:0] temp = SR;
                        temp = {temp[7:0], 1'b0};

                        if (temp[8:1] >= abs_divisor) begin
                            temp[8:1] = temp[8:1] - abs_divisor;
                            temp[0] = 1;
                        end else begin
                            temp[0] = 0;
                        end
                        SR <= temp;
                        cnt <= cnt + 1;
                    end
                end
            end else begin
                res_valid <= 0;
            end
        end
    end

    assign result = {remainder, quotient};

endmodule

