module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] rem;
    reg [15:0] quo;
    integer i;

    rem = 16'b0;
    quo = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = rem << 1;
        rem[0] = a_reg[i];
        if (rem[15:8] >= b_reg) begin
            rem[15:8] = rem[15:8] - b_reg;
            quo[i] = 1'b1;
        end else begin
            quo[i] = 1'b0;
        end
    end

    result = quo;
    odd = rem;
end

endmodule

