module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a + b;
    end else begin

        reg [N-1:0] abs_a, abs_b;
        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;

        if (abs_a > abs_b) begin
            res = a - b;
        end else if (abs_b > abs_a) begin
            res = b - a;
        end else begin
            res = 0;
        end
    end
end

assign c = res;

endmodule

