module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;

    always @(*) begin
        if (same_sign) begin
            res = sign_a ? (b - a) : (a - b);
        end else begin
            if (abs_a > abs_b) begin
                res = {sign_a, abs_a[N-1:1]};
            end else if (abs_b > abs_a) begin
                res = {sign_b, abs_b[N-1:1]};
            end else begin
                res = {1'b0, {(N-1){1'b0}}};
            end
        end
    end


    always @(*) begin
        if (res == {1'b0, {(N-1){1'b0}}}) begin
            res = {1'b0, {(N-1){1'b0}}};
        end
    end

    assign c = res;

endmodule

