module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_reg, b_reg;
    reg a_sign, b_sign;
    reg [7:0] a_exp, b_exp;
    reg [22:0] a_man, b_man;
    reg [23:0] a_man_full, b_man_full;
    reg [47:0] product;
    reg [23:0] norm_mantissa;
    reg [4:0] shift_amount;
    reg [7:0] exp_sum;
    reg [7:0] stored_exp;
    reg guard, round, sticky;
    reg [23:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            a_reg <= 0;
            b_reg <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exp <= 0;
            b_exp <= 0;
            a_man <= 0;
            b_man <= 0;
            a_man_full <= 0;
            b_man_full <= 0;
            product <= 0;
            norm_mantissa <= 0;
            shift_amount <= 0;
            exp_sum <= 0;
            stored_exp <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            rounded_mantissa <= 0;
            z <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_reg <= a;
                    b_reg <= b;
                    counter <= 3'b001;
                end

                3'b001: begin

                    if (a_reg[30:23] == 8'hff && (|a_reg[22:0])) begin

                        z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h1};
                        counter <= 3'b111;
                    end else if (b_reg[30:23] == 8'hff && (|b_reg[22:0])) begin

                        z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h1};
                        counter <= 3'b111;
                    end else if (a_reg[30:23] == 8'hff) begin

                        if (|a_reg[22:0]) begin

                            z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h1};
                            counter <= 3'b111;
                        end else if (b_reg[30:23] == 8'hff) begin
                            if (|b_reg[22:0]) begin

                                z <= {1'b0, 8'hff, 23'h1};
                                counter <= 3'b111;
                            end else begin

                                z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h0};
                                counter <= 3'b111;
                            end
                        end else if (b_reg[30:23] == 0) begin

                            z <= {1'b0, 8'hff, 23'h1};
                            counter <= 3'b111;
                        end else begin

                            z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h0};
                            counter <= 3'b111;
                        end
                    end else if (b_reg[30:23] == 8'hff) begin
                        if (|b_reg[22:0]) begin

                            z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h1};
                            counter <= 3'b111;
                        end else if (a_reg[30:23] == 8'hff) begin
                            if (|a_reg[22:0]) begin

                                z <= {1'b0, 8'hff, 23'h1};
                                counter <= 3'b111;
                            end else begin

                                z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h0};
                                counter <= 3'b111;
                            end
                        end else if (a_reg[30:23] == 0) begin

                            z <= {1'b0, 8'hff, 23'h1};
                            counter <= 3'b111;
                        end else begin

                            z <= {a_reg[31] ^ b_reg[31], 8'hff, 23'h0};
                            counter <= 3'b111;
                        end
                    end else if (a_reg == 0 && b_reg == 0) begin

                        z <= {a_reg[31] ^ b_reg[31], 8'h0, 23'h0};
                        counter <= 3'b111;
                    end else if (a_reg == 0) begin

                        z <= {a_reg[31] ^ b_reg[31], 8'h0, 23'h0};
                        counter <= 3'b111;
                    end else if (b_reg == 0) begin

                        z <= {a_reg[31] ^ b_reg[31], 8'h0, 23'h0};
                        counter <= 3'b111;
                    end else begin

                        a_sign <= a_reg[31];
                        b_sign <= b_reg[31];
                        a_exp <= a_reg[30:23];
                        b_exp <= b_reg[30:23];
                        a_man <= a_reg[22:0];
                        b_man <= b_reg[22:0];
                        a_man_full <= (a_exp != 0) ? {1'b1, a_man} : {1'b0, a_man};
                        b_man_full <= (b_exp != 0) ? {1'b1, b_man} : {1'b0, b_man};
                        counter <= 3'b010;
                    end
                end

                3'b010: begin
                    product <= a_man_full * b_man_full;
                    counter <= 3'b011;
                end

                3'b011: begin
                    if (product == 0) begin

                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 3'b111;
                    end else begin
                        integer i;
                        reg [5:0] leading_one_pos;
                        leading_one_pos = 6'd47;
                        for (i = 47;
 i >= 0;
 i = i - 1) begin
                            if (product[i]) begin
                                leading_one_pos = i;
                                i = -1;
                            end
                        end
                        shift_amount <= 47 - leading_one_pos;
                        exp_sum <= a_exp + b_exp;
                        stored_exp <= exp_sum - 8'd127 + shift_amount;
                        norm_mantissa <= (product << shift_amount) >> 24;
                        guard <= (product << shift_amount) [23];
                        round <= (product << shift_amount) [22];
                        sticky <= |(product << shift_amount) [21:0];
                        counter <= 3'b100;
                    end
                end

                3'b100: begin

                    if (guard && (round || sticky)) begin
                        rounded_mantissa = norm_mantissa + 1;
                        if (rounded_mantissa[23]) begin
                            stored_exp <= stored_exp + 1;
                            if (stored_exp >= 8'hff) begin
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                                counter <= 3'b111;
                            end else begin
                                norm_mantissa <= rounded_mantissa[22:0];
                                counter <= 3'b101;
                            end
                        end else begin
                            norm_mantissa <= rounded_mantissa[22:0];
                            counter <= 3'b101;
                        end
                    end else if (guard && !(round || sticky)) begin
                        if (norm_mantissa[0]) begin
                            rounded_mantissa = norm_mantissa + 1;
                        end else begin
                            rounded_mantissa = norm_mantissa;
                        end
                        if (rounded_mantissa[23]) begin
                            stored_exp <= stored_exp + 1;
                            if (stored_exp >= 8'hff) begin
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                                counter <= 3'b111;
                            end else begin
                                norm_mantissa <= rounded_mantissa[22:0];
                                counter <= 3'b101;
                            end
                        end else begin
                            norm_mantissa <= rounded_mantissa[22:0];
                            counter <= 3'b101;
                        end
                    end else begin
                        counter <= 3'b101;
                    end
                end

                3'b101: begin

                    if (stored_exp >= 8'hff) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (stored_exp == 0) begin

                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin

                        z <= {a_sign ^ b_sign, stored_exp, rounded_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end

                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end

endmodule

