module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);
    reg [1:0] state, next_state;
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            S0: next_state = data_in ? S0 : S1;
            S1: next_state = data_in ? S2 : S0;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

    assign data_out = (state == S2) && (data_in == 0);

endmodule

