module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 60;
                    red <= 1;
                end
                s1_red: begin
                    red <= 0;
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                        green <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    green <= 0;
                    if (pass_request && cnt > 10) begin
                        cnt <= 10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 5;
                        yellow <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    yellow <= 0;
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
                        red <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end

    always @(*) begin
        clock = cnt;
    end

endmodule

