module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] quotient;
reg [7:0] remainder;
reg [3:0] cnt;
reg [16:0] SR;
reg [7:0] divisor_abs;
reg [8:0] neg_divisor;
reg start;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        quotient <= 0;
        remainder <= 0;
        cnt <= 0;
        SR <= 0;
        start <= 0;
        divisor_abs <= 0;
        neg_divisor <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            SR <= { (sign ? (dividend[7] ? -dividend : dividend) : dividend), 8'b0 } << 1;
            neg_divisor <= -divisor_abs;
            quotient <= 0;
            remainder <= 0;
            cnt <= 1;
            start <= 1;
            res_valid <= 0;
        end else if (start) begin
            if (cnt == 8) begin

                start <= 0;
                cnt <= 0;
                res_valid <= 1;
                if (sign) begin
                    remainder <= (dividend[7] && (remainder != 0)) ? -remainder : remainder;
                    quotient <= ((dividend[7] ^ divisor[7]) ? -quotient : quotient);
                end
                result <= {remainder, quotient};
            end else begin

                if (SR[16:9] >= divisor_abs) begin
                    remainder <= SR[16:9] - divisor_abs;
                    quotient <= {quotient[6:0], 1'b1};
                end else begin
                    remainder <= SR[16:9];
                    quotient <= {quotient[6:0], 1'b0};
                end
                SR <= {remainder, quotient} << 1;
                cnt <= cnt + 1;
            end
        end
        if (res_valid && !opn_valid) res_valid <= 0;
    end
end

endmodule

