module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] temp_rem;
    reg [15:0] temp_quotient;

    temp_rem = 0;
    temp_quotient = 0;


    for (int i = 15;
 i >= 0;
 i--) begin
        temp_rem = (temp_rem << 1) | (a_reg[i] ? 1 : 0);

        if (temp_rem >= b_reg) begin
            temp_rem = temp_rem - b_reg;
            temp_quotient = (temp_quotient << 1) | 1;
        end else begin
            temp_quotient = temp_quotient << 1;
        end
    end

    result = temp_quotient;
    odd = temp_rem;
end

endmodule

