    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire borrow_0, borrow_1, borrow_2, borrow_3;

    assign borrow_0 = B[0] & ~A[0];
    assign borrow_1 = (B[1] & ~A[1]) | (borrow_0 & (B[1] | ~A[1]));
