module fixed_point_adder #(
    parameter Q = 4,    
    parameter N = 8     
)(
    input  [N-1:0] a,   
    input  [N-1:0] b,   
    output [N-1:0] c    
);


    wire a_sign = a[N-1];
    wire b_sign = b[N-1];


    wire [N-2:0] mag_a = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] mag_b = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];


    reg [N-1:0] res;

    always @(*) begin
        if (a_sign == b_sign) begin

            res = {a_sign, (mag_a + mag_b)};
        end else begin

            if (mag_a > mag_b) begin
                res = {~a_sign, (mag_a - mag_b)};
            end else if (mag_b > mag_a) begin
                res = {~b_sign, (mag_b - mag_a)};
            end else begin

                res = {1'b0, {(N-2){1'b0}}};
            end
        end
    end


    reg [N-1:0] res_reg;
    always @(*) begin
        res_reg = res;
    end

    assign c = res_reg;

endmodule

