module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exp, b_exp;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [8:0] sum_exp;

    reg [23:0] z_mantissa;

    reg [8:0] z_exp;



    localparam IDLE = 0;
    localparam PROCESS = 1;
    localparam ROUND = 2;
    localparam NORMALIZE = 3;

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;
        end else begin
            case (counter)
                IDLE: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    if (a_exp == 0) a_mantissa <= {1'b0, a[22:0]};
                    else a_mantissa <= {1'b1, a[22:0]};
                    if (b_exp == 0) b_mantissa <= {1'b0, b[22:0]};
                    else b_mantissa <= {1'b1, b[22:0]};


                    if ((a_exp == 8'hFF && a[22:0] != 0) || (b_exp == 8'hFF && b[22:0] != 0)) begin

                        z <= 32'h7FC00000;

                    end else if ((a_exp == 8'hFF && b_exp == 8'hFF) || 
                                (a_exp == 0 && b_exp == 0 && a[22:0] == 0 && b[22:0] == 0)) begin

                        z <= (a_exp == 8'hFF) ? {a_sign, 8'hFF, 23'h0} : {b_sign, 8'hFF, 23'h0};
                    end else if ((a_exp == 0 && a[22:0] == 0) || (b_exp == 0 && b[22:0] == 0)) begin

                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin
                        counter <= PROCESS;
                    end
                end

                PROCESS: begin

                    product <= a_mantissa * b_mantissa;
                    sum_exp <= a_exp + b_exp - 9'd127;
                    counter <= NORMALIZE;
                end

                NORMALIZE: begin

                    if (product[47]) begin
                        z_mantissa <= product >> 1;
                        z_exp <= sum_exp + 9'd1;
                    end else begin
                        z_mantissa <= product;
                        z_exp <= sum_exp;
                    end
                    counter <= ROUND;
                end

                ROUND: begin

                    guard <= z_mantissa[1];
                    round <= z_mantissa[0];
                    sticky <= |z_mantissa[23:2];


                    if (guard) begin
                        if (round || sticky) begin
                            z_mantissa[23] <= 1'b1;
                        end else begin

                            if (z_mantissa[0]) z_mantissa[23] <= 1'b1;
                        end
                    end


                    if (z_mantissa[23]) begin
                        z_mantissa <= z_mantissa >> 1;
                        z_exp <= z_exp + 9'd1;
                    end


                    if (z_exp[8]) begin 
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else if (z_exp >= 9'h100) begin 
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else begin

                        z <= {a_sign ^ b_sign, z_exp[7:0], z_mantissa[22:0]};
                    end

                    counter <= IDLE;
                end
            endcase
        end
    end

endmodule

