module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);


    assign result = A - B;


    wire A_pos = ~A[63];

    wire B_neg = B[63];

    wire result_neg = result[63];



    wire overflow_pos = A_pos & B_neg & result_neg;


    wire A_neg = A[63];

    wire B_pos = ~B[63];

    wire result_pos = ~result[63];



    wire overflow_neg = A_neg & B_pos & result_pos;


    assign overflow = overflow_pos | overflow_neg;

endmodule

