module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg wfull,
    input rclk,
    input rrstn,
    input rinc,
    output reg rempty,
    output reg [WIDTH-1:0] rdata
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_BITS = ADDR_BITS + 1;

reg [PTR_BITS-1:0] waddr_bin, raddr_bin;
wire [PTR_BITS-1:0] wptr_gray, rptr_gray;
reg [PTR_BITS-1:0] rptr_gray_sync0, rptr_gray_sync1;
reg [PTR_BITS-1:0] wptr_gray_sync0, wptr_gray_sync1;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else begin
        if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end
end

assign wptr_gray = waddr_bin ^ (waddr_bin >> 1);


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else begin
        if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end
end

assign rptr_gray = raddr_bin ^ (raddr_bin >> 1);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        {rptr_gray_sync0, rptr_gray_sync1} <= 0;
    end else begin
        rptr_gray_sync0 <= rptr_gray;
        rptr_gray_sync1 <= rptr_gray_sync0;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        {wptr_gray_sync0, wptr_gray_sync1} <= 0;
    end else begin
        wptr_gray_sync0 <= wptr_gray;
        wptr_gray_sync1 <= wptr_gray_sync0;
    end
end


wire full_condition = (wptr_gray[PTR_BITS-1 -: 2] == ~rptr_gray_sync1[PTR_BITS-1 -: 2]) &&
                      (wptr_gray[PTR_BITS-3:0] == rptr_gray_sync1[PTR_BITS-3:0]);


wire empty_condition = (rptr_gray == wptr_gray_sync1);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wfull <= 1'b0;
    end else begin
        wfull <= full_condition;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rempty <= 1'b1;
    end else begin
        rempty <= empty_condition;
    end
end


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wdata(wdata),
    .waddr(waddr_bin[ADDR_BITS-1:0]),
    .wen(winc && !wfull),
    .rclk(rclk),
    .raddr(raddr_bin[ADDR_BITS-1:0]),
    .ren(rinc && !rempty),
    .rdata(rdata)
);

endmodule


module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input [WIDTH-1:0] wdata,
    input [$clog2(DEPTH)-1:0] waddr,
    input wen,
    input rclk,
    input [$clog2(DEPTH)-1:0] raddr,
    input ren,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wen) begin
        RAM_MEM[waddr] <= wdata;
    end
end

always @(posedge rclk) begin
    if (ren) begin
        rdata <= RAM_MEM[raddr];
    end
end

endmodule

