module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle    = 2'b00,
          s1_red  = 2'b01,
          s2_yellow = 2'b10,
          s3_green  = 2'b11;

reg [1:0] state;
reg [7:0] cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s3_green: if (cnt == 0) state <= s2_yellow;
            s2_yellow: if (cnt == 0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        case (state)
            idle: cnt <= 8'd10;
            s1_red: cnt <= (cnt == 0) ? 8'd3 : cnt - 1;
            s3_green: begin
                if (pass_request && cnt > 8'd10)
                    cnt <= 8'd10;
                else
                    cnt <= (cnt == 0) ? 8'd60 : cnt - 1;
            end
            s2_yellow: cnt <= (cnt == 0) ? 8'd5 : cnt - 1;
            default: cnt <= cnt - 1;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        case (state)
            idle: {red, yellow, green} <= 3'b000;
            s1_red: {red, yellow, green} <= 3'b100;
            s3_green: {red, yellow, green} <= 3'b001;
            s2_yellow: {red, yellow, green} <= 3'b010;
            default: {red, yellow, green} <= 3'b000;
        endcase
    end
end


always @(*) clock = cnt;

endmodule

