module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg [7:0] NEG_DIVISOR;
reg sign_reg;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        SR <= 0;
        cnt <= 0;
        NEG_DIVISOR <= 0;
        sign_reg <= 0;
        quotient <= 0;
        remainder <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
                sign_reg <= (dividend[7] ^ divisor[7]);
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
                sign_reg <= 0;
            end


            SR <= {abs_dividend, 8'b0} << 1;
            NEG_DIVISOR <= ~abs_divisor + 1;
            cnt <= 1;
            res_valid <= 0;
            quotient <= 0;
            remainder <= 0;
        end else if (cnt >= 1 && cnt <= 8) begin

            reg [8:0] temp_sum;
            temp_sum = {1'b0, SR[15:8]} + {1'b0, NEG_DIVISOR};

            if (temp_sum[8]) begin

                remainder <= SR[15:8];
                quotient <= {quotient[6:0], 1'b0};
            end else begin

                remainder <= temp_sum[7:0];
                quotient <= {quotient[6:0], 1'b1};
            end

            SR <= {remainder, quotient[6:0]};
            cnt <= cnt + 1;
        end else if (cnt == 9) begin

            cnt <= 0;
            res_valid <= 1;

            if (sign) begin
                remainder = sign_reg ? -remainder : remainder;
                quotient = sign_reg ? -quotient : quotient;
            end
            result <= {remainder, quotient};
        end
    end
end

endmodule

