module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out = 0,
    output reg [9:0] data_out = 0
);

reg [9:0] temp_sum = 0;
reg [1:0] temp_count = 0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        temp_sum <= 0;
        temp_count <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        valid_out <= 0;

        if (valid_in) begin
            temp_sum <= temp_sum + data_in;
            temp_count <= temp_count + 1;
            if (temp_count == 2'b11) begin 
                data_out <= temp_sum + data_in;

                valid_out <= 1;
                temp_sum <= 0;
                temp_count <= 0;
            end
        end
    end
end

endmodule

