module fixed_point_subtractor #(
    parameter Q = 4,    
    parameter N = 8     
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    always @(*) begin

        reg a_sign = a[N-1];
        reg b_sign = b[N-1];
        reg [N-2:0] a_mag = a[N-2:0];

        reg [N-2:0] b_mag = b[N-2:0];
        reg [N-1:0] res;


        if (a_sign == b_sign) begin

            res = {a_sign, a_mag} - {b_sign, b_mag};
        end

        else begin

            if (a_mag >= b_mag) begin
                res = {1'b0, a_mag - b_mag};

            end else begin
                res = {1'b1, b_mag - a_mag};

            end
        end


        if (res == 0) begin
            c = 0;
        end else begin
            c = res;
        end
    end

endmodule

