module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exp, b_exp;
    reg [22:0] a_man, b_man;
    reg [47:0] product;
    reg [9:0] exp_sum;

    reg [47:0] normalized_product;
    reg guard, round, sticky;
    reg [22:0] rounded_man;

    localparam IDLE = 3'b000;
    localparam SPECIAL_CASES = 3'b001;
    localparam MULTIPLY = 3'b010;
    localparam NORMALIZE = 3'b011;
    localparam ROUND = 3'b100;
    localparam ADJUST_EXP = 3'b101;
    localparam FINAL = 3'b110;

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exp <= 0;
            b_exp <= 0;
            a_man <= 0;
            b_man <= 0;
            product <= 0;
            exp_sum <= 0;
            normalized_product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            rounded_man <= 0;
        end else begin
            case (counter)
                IDLE: begin

                    a_sign <= a[31];
                    a_exp <= a[30:23];
                    a_man <= a[22:0];
                    b_sign <= b[31];
                    b_exp <= b[30:23];
                    b_man <= b[22:0];
                    counter <= SPECIAL_CASES;
                end

                SPECIAL_CASES: begin

                    if ((a_exp == 8'hFF && a_man != 0) || (b_exp == 8'hFF && b_man != 0)) begin

                        z <= {1'b0, 8'hFF, a_man[22:0] | b_man[22:0]};
                    end else if ((a_exp == 8'hFF && a_man == 0) && (b_exp == 0 || b_man == 0)) begin

                        z <= {1'b0, 8'hFF, 23'h000001};
                    end else if ((a_exp == 8'hFF && a_man == 0) || (b_exp == 8'hFF && b_man == 0)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                    end else if (a_exp == 0 && b_exp == 0) begin

                        if (a_man == 0 || b_man == 0) begin
                            z <= {a_sign ^ b_sign, 23'h0, 23'h0, 1'b0};
                        end else begin
                            counter <= MULTIPLY;
                        end
                    end else if (a_exp == 0 && a_man == 0) begin

                        z <= {a_sign ^ b_sign, 23'h0, 23'h0, 1'b0};
                    end else if (b_exp == 0 && b_man == 0) begin

                        z <= {a_sign ^ b_sign, 23'h0, 23'h0, 1'b0};
                    end else begin

                        counter <= MULTIPLY;
                    end
                end

                MULTIPLY: begin

                    product <= {1'b1, a_man} * {1'b1, b_man};
                    exp_sum <= a_exp + b_exp - 127;

                    counter <= NORMALIZE;
                end

                NORMALIZE: begin

                    if (product[47]) begin 
                        normalized_product <= product >> 1;
                        exp_sum <= exp_sum + 1;
                    end else begin
                        normalized_product <= product;
                    end

                    {guard, round, sticky} <= {product[0], product[1], |product[47:2]};
                    counter <= ROUND;
                end

                ROUND: begin

                    rounded_man <= normalized_product[46:24];
                    if (guard && (round || sticky || normalized_product[23])) begin
                        rounded_man <= rounded_man + 1;
                        if (rounded_man[23]) begin 
                            exp_sum <= exp_sum + 1;
                            normalized_product <= {1'b0, rounded_man} << 1;
                        end
                    end
                    counter <= ADJUST_EXP;
                end

                ADJUST_EXP: begin

                    if (exp_sum >= 10'h100) begin 
                        z <= {1'b0, 8'hFF, 23'h000000};
                    end else if (exp_sum <= 10'h0) begin 
                        z <= {1'b0, 23'h0, 23'h0};
                    end else begin
                        counter <= FINAL;
                    end
                end

                FINAL: begin

                    z <= {a_sign ^ b_sign, exp_sum[7:0], rounded_man};
                    counter <= IDLE;
                end

                default: counter <= IDLE;
            endcase
        end
    end

endmodule

