module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);


    localparam S0 = 3'b000,
               S1 = 3'b001,
               S2 = 3'b010,
               S3 = 3'b011,
               S4 = 3'b100,
               S5 = 3'b101;

    reg [2:0] current_state, next_state;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin

        next_state = current_state;
        MATCH = 0;

        case (current_state)
            S0: begin
                if (IN) begin
                    next_state = S1;
                end else begin
                    next_state = S0;
                end
                MATCH = 0;
            end
            S1: begin
                if (IN) begin
                    next_state = S1;
                end else begin
                    next_state = S2;
                end
                MATCH = 0;
            end
            S2: begin
                if (IN) begin
                    next_state = S1;
                end else begin
                    next_state = S3;
                end
                MATCH = 0;
            end
            S3: begin
                if (IN) begin
                    next_state = S4;
                end else begin
                    next_state = S0;
                end
                MATCH = 0;
            end
            S4: begin
                if (IN) begin
                    next_state = S5;
                    MATCH = 1;

                end else begin
                    next_state = S0;
                end
                MATCH = 0;
            end
            S5: begin
                if (IN) begin
                    next_state = S1;
                end else begin
                    next_state = S0;
                end
                MATCH = 0;
            end
            default: begin
                next_state = S0;
                MATCH = 0;
            end
        endcase
    end

