        if (Rst) begin

            SP <= 4;
            for (i = 0;
 i < 4;
 i = i + 1) begin
                stack_mem[i] <= 0;
            end
            dataOut <= 0;
        end else if (EN) begin
            if (!RW) begin

                if (!FULL) begin
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                end
            end else begin

                if (!EMPTY) begin
                    dataOut <= stack_mem[SP - 1];
                    stack_mem[SP - 1] <= 0;
                    SP <= SP - 1;
                end
            end
        end
    end

endmodule

