module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s3_green = 2'b10;
    parameter s2_yellow = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;

    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                    cnt <= 10;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_green <= 1;
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && cnt > 10)
                        cnt <= 10;
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_yellow <= 1;
                        cnt <= 5;
                    end else
                        cnt <= cnt - 1;
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_red <= 1;
                        cnt <= 10;
                    end else
                        cnt <= cnt - 1;
                end
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            case (state)
                idle: cnt <= 10;
                s1_red: if (cnt == 0) cnt <= 60;
                s3_green: if (pass_request && cnt > 10) cnt <= 10;
                s2_yellow: if (cnt == 0) cnt <= 10;
                default: cnt <= cnt - 1;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;

endmodule

