    if (!rst_n) begin
        a_prev <= 1'b0;
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        case ({a_prev, a})
            2'b01: begin 
                rise <= 1'b1;
                down <= 1'b0;
            end
            2'b10: begin 
                rise <= 1'b0;
                down <= 1'b1;
            end
            default: begin 
                rise <= 1'b0;
                down <= 1'b0;
            end
        endcase
        a_prev <= a;
    end
end

