module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [3:0] cnt;
    reg [16:0] sr;

    reg [7:0] divisor_abs;
    reg [7:0] dividend_abs;
    reg sign_quotient;
    reg sign_remainder;


    reg [1:0] state;
    parameter IDLE = 2'b00, BUSY = 2'b01, DONE = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            sr <= 0;
            result <= 0;
            cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            sign_quotient <= (dividend[7] ^ divisor[7]);
                            sign_remainder <= dividend[7];
                            dividend_abs <= (dividend[7]) ? (~dividend + 1) : dividend;
                            divisor_abs <= (divisor[7]) ? (~divisor + 1) : divisor;
                        end else begin
                            dividend_abs <= dividend;
                            divisor_abs <= divisor;
                            sign_quotient <= 0;
                            sign_remainder <= 0;
                        end

                        sr <= {dividend_abs, 8'b0} << 1;
                        state <= BUSY;
                        cnt <= 0;
                    end
                end
                BUSY: begin
                    if (cnt < 8) begin

                        sr <= sr << 1;


                        reg [8:0] rem = sr[16:8];
                        reg [9:0] temp = {1'b0, rem} - {1'b0, divisor_abs};
                        if (temp[9]) begin 
                            rem <= temp[8:0];
                        end else begin

                            sr[0] <= 1'b1;
                        end
                        sr[16:8] <= rem;
                        cnt <= cnt + 1;
                    end else begin

                        if (sign) begin
                            if (sign_quotient)
                                sr[7:0] <= ~sr[7:0] + 1;
                            if (sign_remainder)
                                sr[16:9] <= divisor_abs - sr[16:9];
                        end
                        result <= {sr[16:9], sr[7:0]};
                        res_valid <= 1;
                        state <= DONE;
                    end
                end
                DONE: begin
                    if (res_valid) begin
                        res_valid <= 0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

