module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [8:0] remainder;
    reg [15:0] quotient;
    integer i;

    remainder = {1'b0, b_reg};
    quotient = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        reg [8:0] shifted_remainder;
        shifted_remainder = {remainder[7:0], a_reg[i]};

        if (shifted_remainder >= {1'b0, b_reg}) begin
            remainder = shifted_remainder - {1'b0, b_reg};
            quotient[i] = 1;
        end else begin
            remainder = shifted_remainder;
            quotient[i] = 0;
        end
    end

    odd = {7'b0, remainder};
    result = quotient;
end

endmodule

