module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] abs_a, abs_b;
reg sign_a, sign_b;
reg [N-1:0] res;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    abs_a = sign_a ? (~a + 1) : a;
    abs_b = sign_b ? (~b + 1) : b;

    if (sign_a == sign_b) begin

        res = abs_a + abs_b;
        c = {sign_a, res[N-2:0]};
    end else begin

        if (abs_a > abs_b) begin
            res = abs_a - abs_b;
            c = {sign_a, res[N-2:0]};
        end else if (abs_b > abs_a) begin
            res = abs_b - abs_a;
            c = {sign_b, res[N-2:0]};
        end else begin

            c = {1'b0, {N-2{1'b0}}};
        end
    end
end

endmodule

