module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mant, b_mant;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;


    reg [47:0] product_shifted;
    reg [7:0] sum_actual_exponent;
    reg [7:0] sum_exponent;
    reg [7:0] new_exponent;
    reg [22:0] z_mantissa;


    function [7:0] count_leading_zeros(input [47:0] value);
        integer i;
        reg [47:0] temp;
        begin
            temp = value;
            count_leading_zeros = 0;
            for (i = 47;
 i >= 0;
 i = i - 1) begin
                if (temp[i]) break;
                count_leading_zeros = count_leading_zeros + 1;
            end
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            z_exponent <= 8'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            product <= 48'b0;
        end else begin
            case (counter)

                3'b0: begin
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];
                    counter <= counter + 1;
                end


                3'b1: begin

                    if ((a_exponent == 8'hFF && a_mantissa != 0) || (b_exponent == 8'hFF && b_mantissa != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                        counter <= 3'b0;
                    end

                    else if ((a_exponent == 8'hFF && a_mantissa == 0) || (b_exponent == 8'hFF && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                        counter <= 3'b0;
                    end

                    else if ((a_exponent == 8'h00 && a_mantissa == 23'b0) || (b_exponent == 8'h00 && b_mantissa == 23'b0)) begin
                        z <= {1'b0, 8'b0, 23'b0};
                        counter <= 3'b0;
                    end
                    else begin

                        a_mant <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                        b_mant <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                        counter <= counter + 1;
                    end
                end


                3'b2: begin
