module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output [WIDTH-1:0] rdata,
    output rempty
);

    localparam PTR_WIDTH = $clog2(DEPTH);
    reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
    wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;
    reg [PTR_WIDTH-1:0] rptr_gray_sync0, rptr_gray_sync1;
    reg [PTR_WIDTH-1:0] wptr_gray_sync0, wptr_gray_sync1;
    wire [PTR_WIDTH-1:0] rptr_bin_sync;
    wire wenc, renc;

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(wptr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(rptr_bin),
        .rdata(rdata)
    );


    always @(posedge wclk) begin
        if (!wrstn) wptr_bin <= 0;
        else if (winc && !wfull) wptr_bin <= wptr_bin + 1;
    end

    assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
    assign wenc = winc && !wfull;


    always @(posedge wclk) begin
        if (!wrstn) begin
            rptr_gray_sync0 <= 0;
            rptr_gray_sync1 <= 0;
        end
        else begin
            rptr_gray_sync0 <= rptr_gray;
            rptr_gray_sync1 <= rptr_gray_sync0;
        end
    end

    function [PTR_WIDTH-1:0] gray_to_binary;
        input [PTR_WIDTH-1:0] gray;
        reg [PTR_WIDTH-1:0] binary;
        begin
            binary[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (int i = PTR_WIDTH-2;
 i >= 0;
 i--)
                binary[i] = binary[i+1] ^ gray[i];
            gray_to_binary = binary;
        end
    endfunction

    wire [PTR_WIDTH-1:0] rptr_bin_sync = gray_to_binary(rptr_gray_sync1);
    wire [PTR_WIDTH-1:0] rptr_plus_half = rptr_bin_sync + (DEPTH >> 1);
    wire [PTR_WIDTH-1:0] expected_gray_full = (rptr_plus_half >> 1) ^ rptr_plus_half;
    assign wfull = (wptr_gray == expected_gray_full);


    always @(posedge rclk) begin
        if (!rrstn) rptr_bin <= 0;
        else if (rinc && !rempty) rptr_bin <= rptr_bin + 1;
    end

    assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;
    assign renc = rinc && !rempty;


    always @(posedge rclk) begin
        if (!rrstn) begin
            wptr_gray_sync0 <= 0;
            wptr_gray_sync1 <= 0;
        end
        else begin
            wptr_gray_sync0 <= wptr_gray;
            wptr_gray_sync1 <= wptr_gray_sync0;
        end
    end

    assign rempty = (rptr_gray == wptr_gray_sync1);

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
