    if (!rst_n)
        data_loaded <= 1'b0;
    else if (cnt == 2'b11)
        data_loaded <= 1'b1;
end


always @(*) begin
    if (!rst_n)
        valid_out = 1'b0;
    else if (data_loaded)
        valid_out = (cnt <= 2'b11);
    else
        valid_out = 1'b0;
end


always @(*) begin
    case (cnt)
        2'b00: dout = data[3];
        2'b01: dout = data[2];
        2'b10: dout = data[1];
        2'b11: dout = data[0];
        default: dout = 1'b0;
    endcase
end

