module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle    = 2'b00;
    parameter s1_red  = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= s1_red;
            cnt <= 8'd10;
            clock <= 8'd10;
        end else begin
            clock <= cnt;
            case (state)
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 8'd3;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 8'd3;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 8'd3;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: begin
                    state <= s1_red;
                    cnt <= 8'd3;
                end
            endcase


            if (pass_request && green) begin
                cnt <= 8'd10;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;

            case (state)
                s1_red: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                s3_green: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end
                s2_yellow: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
            endcase
        end
    end

endmodule

