module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg [7:0] data_lock;
    reg has_first_data;
    reg [7:0] data_buffer;
    reg valid_buffer;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            valid_out <= 1'b0;
            data_lock <= 8'b0;
            has_first_data <= 1'b0;
            data_buffer <= 8'b0;
            valid_buffer <= 1'b0;
        end else begin

            valid_out <= 1'b0;
            valid_buffer <= 1'b0;

            if (valid_in) begin
                if (has_first_data) begin

                    data_buffer <= {data_lock, data_in};
                    valid_buffer <= 1'b1;
                    has_first_data <= 1'b0;
                end else begin

                    data_lock <= data_in;
                    has_first_data <= 1'b1;
                end
            end


            if (valid_buffer) begin
                data_out <= {data_buffer, 8'b0};


                data_out <= data_buffer;
                valid_out <= 1'b1;
            end
        end
    end

endmodule

