module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] rem_quot;
    reg [3:0] cnt;
    reg div_complete;
    reg dividend_sign, divisor_sign;
    reg [7:0] abs_dividend, abs_divisor;
    reg state;

    localparam IDLE = 0;
    localparam DIVIDING = 1;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            rem_quot <= 0;
            cnt <= 0;
            div_complete <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        dividend_sign <= sign ? dividend[7] : 0;
                        divisor_sign <= sign ? divisor[7] : 0;
                        abs_dividend <= sign ? ((dividend[7]) ? (~dividend + 1) : dividend) : dividend;
                        abs_divisor <= sign ? ((divisor[7]) ? (~divisor + 1) : divisor) : divisor;

                        rem_quot <= {8'b0, abs_dividend};
                        cnt <= 0;
                        div_complete <= 0;
                        state <= DIVIDING;
                    end
                end
                DIVIDING: begin
                    if (!div_complete) begin
                        if (cnt < 8) begin

                            rem_quot <= rem_quot << 1;
                            rem_quot[15:8] <= rem_quot[15:8] - abs_divisor;

                            if (rem_quot[15:8] >= abs_divisor) begin
                                rem_quot[0] <= 1;
                            end else begin
                                rem_quot[15:8] <= rem_quot[15:8] + abs_divisor;
                                rem_quot[0] <= 0;
                            end
                            cnt <= cnt + 1;
                        end else begin

                            if (sign) begin
                                if (dividend_sign ^ divisor_sign) begin
                                    rem_quot[7:0] <= ~rem_quot[7:0] + 1;

                                end
                                if (dividend_sign) begin
                                    rem_quot[15:8] <= ~rem_quot[15:8] + 1;

                                end
                            end
                            result <= rem_quot;
                            res_valid <= 1;
                            state <= IDLE;
                        end
                    end
                end
            endcase
        end
    end

endmodule

