module fixed_point_adder #(
    parameter Q = 4, 
    parameter N = 8  
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] diff;
    reg sign;

    always @(*) begin

        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            c = a + b;
        end else begin

            if (abs_a > abs_b) begin
                diff = abs_a - abs_b;
                sign = a[N-1];
            end else if (abs_b > abs_a) begin
                diff = abs_b - abs_a;
                sign = b[N-1];
            end else begin
                diff = 0;
                sign = 0;
            end

            c = {sign, diff[N-2:0]};
        end
    end

endmodule

