            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 10;
                    {p_red, p_yellow, p_green} <= 3'b100;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                        {p_red, p_yellow, p_green} <= 3'b001;
                    end else begin
                        cnt <= cnt - 1;
                    end
