                s3_green: begin
                    if (pass_request && p_green) begin
                        if (cnt > 10) begin
                            cnt <= 10;
                        end
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 5;
                        {p_red, p_yellow, p_green} <= 3'b010;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
