module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg flag_reg;
wire [31:0] res;
wire [32:0] sum_33, sub_33;
wire [4:0] shamt;
wire [31:0] shifted;

assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;
assign zero = (r == 32'b0);
assign negative = r[31];

always @(*) begin
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = 1'b0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = 1'b0;
        end
        AND: r = a & b;
        OR:  r = a | b;
        XOR: r = a ^ b;
        NOR: r = ~(a | b);
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
            flag_reg = ($signed(a) < $signed(b));
        end
        SLTU: begin
            r = (a < b) ? 32'b1 : 32'b0;
            flag_reg = (a < b);
        end
        SLL: begin
            r = a << a[4:0];
        end
        SRL: begin
            r = a >> a[4:0];
        end
        SRA: begin
            r = $signed(a) >>> a[4:0];
        end
        SLLV: begin
            r = b << a[4:0];
        end
        SRLV: begin
            r = b >> a[4:0];
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
        end
        LUI: r = {a[15:0], 16'b0};
        default: r = 32'bz;
    endcase
    if (aluc == SLT || aluc == SLTU) begin
        overflow = 1'b0;
        carry = 1'b0;
    end else begin
        overflow = 1'b0;
        carry = 1'b0;
    end
end

endmodule

