module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [1:0] sign_reg;
reg [15:0] SR;

reg [3:0] cnt;
reg start_cnt;

wire [7:0] NEG_DIVISOR = -abs_divisor;
wire [7:0] SR_remainder = SR[15:8];
wire [7:0] SR_quotient = SR[7:0];
wire [8:0] sub_res = SR_remainder - NEG_DIVISOR;
wire carry = ~sub_res[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 16'h0;
        cnt <= 0;
        start_cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        sign_reg <= 0;
        result <= 16'h0;
    end else begin
        if (opn_valid && !res_valid) begin

            abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            sign_reg <= {dividend[7], divisor[7]};

            SR <= {abs_dividend, 8'b0} << 1;
            cnt <= 0;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin

                if (carry) begin
                    SR[15:8] <= sub_res[7:0];
                    SR[7:0] <= (SR_quotient << 1) | 1'b1;
                end else begin
                    SR[7:0] <= (SR_quotient << 1) | 1'b0;
                end
                cnt <= cnt + 1;
            end else begin

                start_cnt <= 0;
                if (sign) begin

                    if (sign_reg[0]) result[15:8] <= -SR_remainder;
                    else result[15:8] <= SR_remainder;

                    if (sign_reg[0] ^ sign_reg[1]) result[7:0] <= -SR_quotient;
                    else result[7:0] <= SR_quotient;
                end else begin
                    result <= {SR_remainder, SR_quotient};
                end
                res_valid <= 1;
            end
        end else if (res_valid) begin
            res_valid <= 0;
        end
    end
end

endmodule

