module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [4:0] sum_bin = A + B + Cin;
wire [3:0] sum_temp = sum_bin[3:0];
wire carry_temp = sum_bin[4];
wire correction_needed = (sum_temp > 9) || carry_temp;

