module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg s_a, s_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] sum_abs;
    reg [N-1:0] diff_abs;
    reg sign;
    reg [N-1:0] res;

    always @(*) begin
        s_a = a[N-1];
        s_b = b[N-1];
        abs_a = s_a ? (~a + 1) : a;
        abs_b = s_b ? (~b + 1) : b;

        if (s_a == s_b) begin
            sum_abs = abs_a + abs_b;
            sign = s_a;

            if (sum_abs > (2**(N-1) - 1)) begin
                res = {sign, {N-1{1'b1}}};

            end else begin
                res = {sign, sum_abs};
            end
        end else begin
            if (abs_a > abs_b) begin
                diff_abs = abs_a - abs_b;
                sign = s_a;
            end else if (abs_b > abs_a) begin
                diff_abs = abs_b - abs_a;
                sign = s_b;
            end else begin
                diff_abs = 0;
                sign = 0;
            end
            res = {sign, diff_abs};
        end
        c = res;
    end

endmodule

