module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard_bit, round_bit, sticky;
reg [7:0] z_exponent;
reg [22:0] z_mantissa;
reg is_nan, is_inf, is_zero;


reg [47:0] normalized_product;
reg [4:0] shift_amount;


always @(*) begin
    is_nan = (a[30:23] == 8'hFF && a[22:0] != 0) || (b[30:23] == 8'hFF && b[22:0] != 0);
    is_inf = (a[30:23] == 8'hFF && a[22:0] == 0) || (b[30:23] == 8'hFF && b[22:0] == 0);
    is_zero = (a[30:23] == 0 && a[22:0] == 0) || (b[30:23] == 0 && b[22:0] == 0);
end


function automatic [4:0] leading_one (input [47:0] val);
    integer i;
    begin
        leading_one = 0;
        for (i = 47;
 i >= 0;
 i = i - 1)
            if (val[i]) begin
                leading_one = i;
                break;
            end
    end
endfunction

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        z_exponent <= 0;
        z_mantissa <= 0;
    end else begin
        case (counter)
            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];
                counter <= 1;
            end
            1: begin
                if (is_nan || (is_inf && is_zero)) begin
                    z <= 32'h7FC00000;
                    counter <= 0;
                end else if (is_zero) begin
                    z <= {a_sign ^ b_sign, 31'b0};
                    counter <= 0;
                end else if (is_inf) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                    counter <= 0;
                end else begin
                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    counter <= 2;
                end
            end
            2: begin
                shift_amount <= 47 - leading_one(product);
                normalized_product <= product >> shift_amount;
                z_exponent <= a_exponent + b_exponent + shift_amount - 127;
                counter <= 3;
            end
            3: begin

                {guard_bit, round_bit, sticky} <= normalized_product[23:21];
                z_mantissa <= normalized_product[46:24];
                counter <= 4;
            end
            4: begin

                if (guard_bit && (round_bit || sticky || (normalized_product[23] && guard_bit))) begin
                    z_mantissa <= z_mantissa + 1;
                    if (z_mantissa[22:0] == 23'h7FFFFF) begin 
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= 23'h0;
                    end
                end
                counter <= 5;
            end
            5: begin

                if (z_exponent > 254) begin
