module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;

parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 10;
        {red, yellow, green} <= 3'b000;
    end else begin
        case (state)
            idle: begin
                state <= s1_red;
                {red, yellow, green} <= 3'b100;

            end
            s1_red: begin
                if (cnt == 3) begin
                    state <= s3_green;
                    cnt <= 60;
                    {red, yellow, green} <= 3'b001;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            s3_green: begin
                if (pass_request && (cnt > 10)) 
                    cnt <= 10;
                if (cnt == 3) begin
                    state <= s2_yellow;
                    cnt <= 5;
                    {red, yellow, green} <= 3'b010;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            s2_yellow: begin
                if (cnt == 3) begin
                    state <= s1_red;
                    cnt <= 10;
                    {red, yellow, green} <= 3'b100;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            default: state <= idle;
        endcase
    end
end

assign clock = cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 3'b000;
    end else begin
        {p_red, p_yellow, p_green} <= {red, yellow, green};
    end
end

assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;

endmodule

