            valid_out <= 1'b0;

            if (valid_in) begin
                if (!has_data) begin

                    data_lock <= data_in;
                    has_data <= 1'b1;
                end else begin

                    data_reg <= {data_lock, data_in};
                    valid_reg <= 1'b1;
                    has_data <= 1'b0;
                end
            end

            data_out <= data_reg;
            valid_out <= valid_reg;
        end
    end

