module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r = 0,
    output zero,
    output reg carry = 0,
    output negative,
    output reg overflow = 0,
    output reg flag = 0
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    assign zero = (r == 32'b0);
    assign negative = r[31];

    reg [32:0] sum;
    reg temp_carry;
    reg temp_overflow;
    reg [31:0] temp_r;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum = {1'b0, a} + {1'b0, b};
                temp_r = sum[31:0];
                temp_carry = sum[32];
                temp_overflow = (a[31] == b[31]) && (sum[31] != a[31]);
                flag = 'bz;
            end
            ADDU: begin
                sum = {1'b0, a} + {1'b0, b};
                temp_r = sum[31:0];
                temp_carry = sum[32];
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SUB: begin
                sum = {1'b0, a} - {1'b0, b};
                temp_r = sum[31:0];
                temp_carry = sum[32];
                temp_overflow = (a[31] != b[31]) && (sum[31] != a[31]);
                flag = 'bz;
            end
            SUBU: begin
                sum = {1'b0, a} - {1'b0, b};
                temp_r = sum[31:0];
                temp_carry = sum[32];
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            AND: begin
                temp_r = a & b;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            OR: begin
                temp_r = a | b;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            XOR: begin
                temp_r = a ^ b;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            NOR: begin
                temp_r = ~(a | b);
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SLT: begin
                temp_r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = temp_r[0];
            end
            SLTU: begin
                temp_r = (a < b) ? 32'd1 : 32'd0;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = temp_r[0];
            end
            SLL: begin
                temp_r = b << a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SRL: begin
                temp_r = b >> a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SRA: begin
                temp_r = $signed(b) >>> a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SLLV: begin
                temp_r = b << a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SRLV: begin
                temp_r = b >> a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            SRAV: begin
                temp_r = $signed(b) >>> a[4:0];
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            LUI: begin
                temp_r = {a[15:0], 16'b0};
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
            default: begin
                temp_r = 32'bz;
                temp_carry = 1'b0;
                temp_overflow = 1'b0;
                flag = 'bz;
            end
        endcase

        r = temp_r;
        carry = temp_carry;
        overflow = temp_overflow;
    end

endmodule

