module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg sign_quotient;
    reg sign_remainder;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [3:0] counter;
    reg [7:0] divisor_reg;
    reg [1:0] state;

    localparam S_IDLE = 0;
    localparam S_CALC = 1;
    localparam S_DONE = 2;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            res_valid <= 0;
            counter <= 0;
            remainder <= 0;
            quotient <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            dividend_abs = dividend[7] ? -dividend : dividend;
                            divisor_abs = divisor[7] ? -divisor : divisor;
                            sign_quotient = dividend[7] ^ divisor[7];
                            sign_remainder = dividend[7];
                        end else begin
                            dividend_abs = dividend;
                            divisor_abs = divisor;
                            sign_quotient = 0;
                            sign_remainder = 0;
                        end


                        remainder <= {8'b0, dividend_abs};
                        divisor_reg <= divisor_abs;
                        quotient <= 0;
                        counter <= 0;
                        state <= S_CALC;
                    end
                end

                S_CALC: begin
                    if (counter < 8) begin

                        {remainder, quotient} = {remainder[6:0], quotient[7:1], quotient[0]};


                        if (remainder[7]) begin

                            remainder = remainder + divisor_reg;
                        end else begin

                            remainder = remainder - divisor_reg;
                        end


                        quotient[0] = !remainder[7];

                        counter <= counter + 1;
                    end else begin

                        if (sign) begin
                            if (sign_quotient) quotient = -quotient;
                            if (sign_remainder) remainder = -remainder;
                        end


                        result <= {remainder, quotient};
                        res_valid <= 1;
                        state <= S_DONE;
                    end
                end

                S_DONE: begin
                    res_valid <= 0;
                    state <= S_IDLE;
                end
            endcase
        end
    end

endmodule

