            accumulator <= 10'b0;
            counter <= 2'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            valid_out <= 1'b0;


            if (valid_in) begin
                accumulator <= accumulator + data_in;
                counter <= counter + 1;

                if (counter == 2'b11) begin
                    data_out <= accumulator + data_in;
                    valid_out <= 1'b1;
                end
            end
        end
    end

endmodule

