module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_reg, b_reg;
    reg [23:0] a_mantissa, b_mantissa;
    reg [9:0] a_exponent, b_exponent;
    reg a_sign, b_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [9:0] z_exponent;
    reg z_sign;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 1;
                end
                1: begin

                    if (a_exponent == 9'hFE || b_exponent == 9'hFE) begin
                        z <= {1'b0, 8'hFF, 23'h0};

                        counter <= 0;
                    end else if (a_exponent == 0 || b_exponent == 0) begin

                        z <= 32'h0;
                        counter <= 0;
                    end else if (a_exponent == 9'hFF || b_exponent == 9'hFF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        counter <= 0;
                    end else begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 10'd127;
                        product <= a_mantissa * b_mantissa;
                        counter <= 2;
                    end
                end
                2: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 3;
                end
                3: begin

                    z_mantissa <= product[46:24];
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 4;
                end
                4: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        if (z_mantissa == 23'h7FFFFF) begin
                            z_mantissa <= 0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 5;
                end
                5: begin

                    if (z_exponent > 9'h1FE) begin
                        z <= {z_sign, 8'hFF, 23'h0};

                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 8'h0, 23'h0};

                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

endmodule

