module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [3:0] SP;

reg [3:0] new_SP;

always @(posedge Clk) begin
    if (Rst) begin

        SP <= 4;
        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 0;
        for (integer i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 0;
        end
    end else if (EN) begin
        new_SP = SP;

        if (RW == 0) begin 
            if (!FULL) begin
                new_SP = SP - 1;
                stack_mem[new_SP] <= dataIn;
            end
        end else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 0;
                new_SP = SP + 1;
            end
        end

        EMPTY <= (new_SP == 4);
        FULL <= (new_SP == 0);
        SP <= new_SP;

    end
end

endmodule

