module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result = 0
);

    reg [7:0] abs_dividend, abs_divisor;
    reg q_sign, r_sign;
    reg [15:0] SR;

    reg [3:0] cnt = 0;
    reg start;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            q_sign <= 0;
            r_sign <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    q_sign <= dividend[7] ^ divisor[7];
                    r_sign <= dividend[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    q_sign <= 0;
                    r_sign <= 0;
                end

                SR <= {abs_dividend, 8'b0} << 1;
                start <= 1;
                cnt <= 1;
                res_valid <= 0;
            end else if (start) begin
                if (cnt == 8) begin

                    start <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        if (q_sign) result[7:0] <= -SR[7:0];
                        if (r_sign) result[15:8] <= -SR[15:8];
                    end
                end else begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR[0] <= 1'b1;

                    end
                    SR <= SR << 1;

                    cnt <= cnt + 1;
                end
            end

            if (res_valid && opn_valid) res_valid <= 0;
        end
    end

endmodule

