module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;


always @(A, B) begin
    a_reg = A;
    b_reg = B;
end


always @(a_reg, b_reg) begin
    reg [15:0] remainder = 0;
    reg [15:0] quotient = 0;
    integer i;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = (remainder << 1) | (a_reg[i]);
        if (remainder >= {8'b0, b_reg}) begin
            remainder = remainder - {8'b0, b_reg};
            quotient[i] = 1;
        end else begin
            quotient[i] = 0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

