    assign C1 = G_bit[0] | (P_bit[0] & Cin);
    assign C2 = G_bit[1] | (P_bit[1] & G_bit[0]) | (P_bit[1] & P_bit[0] & Cin);
    assign C3 = G_bit[2] | (P_bit[2] & G_bit[1]) | (P_bit[2] & P_bit[1] & G_bit[0]) | (P_bit[2] & P_bit[1] & P_bit[0] & Cin);
    assign C4 = G_bit[3] | (P_bit[3] & G_bit[2]) | (P_bit[3] & P_bit[2] & G_bit[1]) | (P_bit[3] & P_bit[2] & P_bit[1] & G_bit[0]) | (P_bit[3] & P_bit[2] & P_bit[1] & P_bit[0] & Cin);

    assign S[0] = P_bit[0] ^ Cin;
    assign S[1] = P_bit[1] ^ C1;
    assign S[2] = P_bit[2] ^ C2;
    assign S[3] = P_bit[3] ^ C3;

    assign G = G_bit[3] | (P_bit[3] & G_bit[2]) | (P_bit[3] & P_bit[2] & G_bit[1]) | (P_bit[3] & P_bit[2] & P_bit[1] & G_bit[0]);
