module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam idle = 2'b00;
    localparam s1_red = 2'b01;
    localparam s2_yellow = 2'b10;
    localparam s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            red <= 0;
            yellow <= 0;
            green <= 0;
            clock <= 0;
        end else begin
            state <= next_state;


            if (pass_request && green && cnt > 10)
                cnt <= 8'd10;
            else if (!green && p_green)
                cnt <= 8'd60;
            else if (!yellow && p_yellow)
                cnt <= 8'd5;
            else if (!red && p_red)
                cnt <= 8'd10;
            else
                cnt <= cnt - 1;


            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;


            case (state)
                idle: {red, yellow, green} <= 3'b000;
                s1_red: {red, yellow, green} <= 3'b100;
                s3_green: {red, yellow, green} <= 3'b001;
                s2_yellow: {red, yellow, green} <= 3'b010;
                default: {red, yellow, green} <= 3'b000;
            endcase

            clock <= cnt;
        end
    end


    always @(*) begin
        next_state = state;
        case (state)
            idle: next_state = s1_red;
            s1_red: if (cnt == 3) next_state = s3_green;
            s3_green: if (cnt == 3) next_state = s2_yellow;
            s2_yellow: if (cnt == 3) next_state = s1_red;
            default: next_state = idle;
        endcase
    end

endmodule

