module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD      = 6'b100000;
    parameter ADDU     = 6'b100001;
    parameter SUB      = 6'b100010;
    parameter SUBU     = 6'b100011;
    parameter AND      = 6'b100100;
    parameter OR       = 6'b100101;
    parameter XOR      = 6'b100110;
    parameter NOR      = 6'b100111;
    parameter SLT      = 6'b101010;
    parameter SLTU     = 6'b101011;
    parameter SLL      = 6'b000000;
    parameter SRL      = 6'b000010;
    parameter SRA      = 6'b000011;
    parameter SLLV     = 6'b000100;
    parameter SRLV     = 6'b000110;
    parameter SRAV     = 6'b000111;
    parameter LUI      = 6'b001111;

    reg carry_reg;
    reg overflow_reg;
    reg flag_reg;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = carry_reg;
    assign overflow = overflow_reg;
    assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;

    always @(*) begin
        case(aluc)
            ADD: begin
                {carry_reg, r} = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                {carry_reg, r} = {1'b0, a} + {1'b0, b};
                overflow_reg = 0;
            end
            SUB: begin
                {carry_reg, r} = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                {carry_reg, r} = {1'b0, a} - {1'b0, b};
                overflow_reg = 0;
            end
            AND: begin
                r = a & b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            OR: begin
                r = a | b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            XOR: begin
                r = a ^ b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            NOR: begin
                r = ~(a | b);
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLT: begin
                flag_reg = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
                r = {31'b0, flag_reg};
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLTU: begin
                flag_reg = (a < b) ? 1'b1 : 1'b0;
                r = {31'b0, flag_reg};
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLL: begin
                r = b << a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRL: begin
                r = b >> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRA: begin
                r = $signed(b) >>> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLLV: begin
                r = a << b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRLV: begin
                r = a >> b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRAV: begin
                r = $signed(a) >>> b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            LUI: begin
                r = {b[15:0], 16'b0};
                carry_reg = 0;
                overflow_reg = 0;
            end
            default: begin
                r = 32'bz;
                carry_reg = 0;
                overflow_reg = 0;
            end
        endcase
    end

endmodule

