module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result = 0
);

reg [8:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [7:0] neg_divisor;
reg [7:0] quotient;
reg remainder_sign, quotient_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        SR <= 0;
        quotient <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                neg_divisor <= divisor[7] ? (~divisor + 1) : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
                neg_divisor <= ~divisor + 1;
            end


            SR <= {abs_dividend, 1'b0};
            start_cnt <= 1;
            cnt <= 1;
        end

        if (start_cnt) begin
            if (cnt <= 8) begin

                if (SR[8]) begin 
                    quotient <= (quotient << 1) | 0;
                    SR <= {SR[7:0], 1'b0};
                end else begin
                    SR <= SR - abs_divisor;
                    quotient <= (quotient << 1) | 1;
                    SR <= {SR[7:0], 1'b0};
                end
                cnt <= cnt + 1;
            end else begin

                result <= {SR[8:1], quotient};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end
        end

        if (!start_cnt && cnt == 8) begin

            if (sign) begin
                remainder_sign <= dividend[7];
                quotient_sign <= (dividend[7] ^ divisor[7]);
                if (remainder_sign)
                    result[15:8] <= ~result[15:8] + 1;
                if (quotient_sign)
                    result[7:0] <= ~result[7:0] + 1;
            end
            res_valid <= 0;
        end
    end
end

endmodule

