module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result = 0,
    output reg [15:0] odd = 0
);

reg [7:0] a_reg, b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    integer i;
    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [15:0] dividend;

    dividend = a_reg;
    quotient = 0;
    remainder = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = (remainder << 1) | ((dividend >> i) & 1);
        if (remainder >= b_reg) begin
            remainder = remainder - b_reg;
            quotient[i] = 1;
        end else begin
            quotient[i] = 0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

