module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    wire [4:0] bin_sum = A + B + Cin;
    wire condition = (bin_sum[3:0] > 4'd9) || bin_sum[4];

    wire [4:0] sum_plus_correction = bin_sum[3:0] + (condition ? 4'd6 : 4'd0);

    assign Sum = sum_plus_correction[3:0];
    assign Cout = bin_sum[4] | sum_plus_correction[4];

endmodule

