module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output G_group,
    output P_group
);


    wire [16:1] G_bits, P_bits;
    assign G_bits[1] = A[1] & B[1];
    assign P_bits[1] = A[1] ^ B[1];

    genvar i;
    generate
        for (i = 2;
 i <= 16;
 i = i + 1) begin : cla_bits
            assign G_bits[i] = A[i] & B[i];
            assign P_bits[i] = A[i] ^ B[i];
        end
    endgenerate


    wire [16:1] G_terms, P_terms;
    assign G_terms[1] = G_bits[1];
    assign P_terms[1] = P_bits[1];

    genvar j;
    generate
        for (j = 2;
 j <= 16;
 j = j + 1) begin : prefix
            assign G_terms[j] = G_bits[j] | (P_terms[j-1] & G_terms[j-1]);
            assign P_terms[j] = P_terms[j-1] & P_bits[j];
        end
    endgenerate

    assign G_group = G_terms[16];
    assign P_group = P_terms[16];


    wire [17:1] C;
    assign C[0] = Cin;

    genvar k;
    generate
        for (k = 1;
 k <= 16;
 k = k + 1) begin : carry
            assign C[k] = G_bits[k] | (P_bits[k] & C[k-1]);
        end
    endgenerate


    assign S = (A ^ B) ^ C[16:1];

endmodule

