module fixed_point_adder #(parameter Q = 4, N = 8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);


wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;


wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);

always @(*) begin
    if (same_sign) begin

        c = abs_a + abs_b;
        c[N-1] = sign_a;
    end else begin

        if (abs_a > abs_b) begin
            c = abs_a - abs_b;
            c[N-1] = sign_a;
        end else if (abs_b > abs_a) begin
            c = abs_b - abs_a;
            c[N-1] = sign_b;
        end else begin

            c = {N{1'b0}};
        end
    end
end

endmodule

