module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter;
reg [31:0] a_reg, b_reg;
reg a_sign, b_sign;
reg [7:0] a_exp, b_exp;
reg [22:0] a_mant, b_mant;
reg [4:0] exp_sum;
reg product_sign;
reg [47:0] product;
reg [23:0] z_mant;
reg [9:0] z_exp;
reg guard, round, sticky;
reg sticky_or;


wire a_is_nan = (a_exp == 8'hff) && (a_mant != 0);
wire b_is_nan = (b_exp == 8'hff) && (b_mant != 0);
wire a_is_inf = (a_exp == 8'hff) && (a_mant == 0);
wire b_is_inf = (b_exp == 8'hff) && (b_mant == 0);
wire a_is_zero = (a_exp == 0) && (a_mant == 0);
wire b_is_zero = (b_exp == 0) && (b_mant == 0);
wire inf_case = (a_is_inf || b_is_inf);
wire zero_case = (a_is_zero || b_is_zero);

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;

    end else begin
        case (counter)
            0: begin

                a_reg <= a;
                b_reg <= b;
                a_sign <= a[31];
                b_sign <= b[31];
                a_exp <= a[30:23];
                b_exp <= b[30:23];
                a_mant <= a[22:0];
                b_mant <= b[22:0];
                product_sign <= a_sign ^ b_sign;
                counter <= 1;
            end
            1: begin

                if (a_is_nan || b_is_nan || inf_case && zero_case) begin
                    z <= {product_sign, 8'hff, 23'h0};

                    counter <= 0;
                end else if (inf_case && !(zero_case)) begin
                    z <= {product_sign, 8'hff, 23'h0};

                    counter <= 0;
                end else if (zero_case) begin
                    z <= {product_sign, 9'b0, 23'b0};

                    counter <= 0;
                end else begin

                    exp_sum <= a_exp + b_exp;

                    product <= {1'b1, a_mant} * {1'b1, b_mant};
                    counter <= 2;
                end
            end
            2: begin


                integer i;
                reg [47:0] shifted_product;
                reg [9:0] shift_amount;
                reg [47:0] temp;
                temp = product;
                for (i = 0;
 i < 48;
 i = i + 1) begin
                    if (temp[47 - i]) begin
                        shifted_product = temp << i;
                        shift_amount = i;
                        break;
                    end
                end

                z_exp = exp_sum - 9'd127 + shift_amount;

                z_mant = shifted_product[46:23];

                guard = shifted_product[22];
                round = shifted_product[21];
                sticky = |shifted_product[20:0];
                sticky_or = guard & (round | sticky);
                if (round && (sticky || guard)) begin
                    if (sticky_or || (round && !sticky)) begin

                        if (z_mant[0]) begin
                            z_mant = z_mant + 1;

                            if (z_mant[23]) begin
                                z_mant = 24'h800000;
                                z_exp = z_exp + 1;
                            end
                        end
                    end
                end
                counter <= 3;
            end
            3: begin

                if (z_exp >= 9'h1fe) begin 
                    z <= {product_sign, 8'hff, 23'h0};
                end else if (z_exp <= 9'h0) begin 
                    z <= {product_sign, 9'h0, 23'h0};
                end else begin

                    z <= {product_sign, z_exp[7:0], z_mant[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

