assign wgray = (wbin >> 1) ^ wbin;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rgray_sync[0] <= 0;
        rgray_sync[1] <= 0;
    end else begin
        rgray_sync[0] <= rgray;
        rgray_sync[1] <= rgray_sync[0];
    end
