function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
    integer i;
    reg [PTR_WIDTH-1:0] bin;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i-1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

wire [PTR_WIDTH-1:0] rbin_sync = gray2bin(rgray_sync[1]);


assign wfull = (wgray[PTR_WIDTH-1] != rbin_sync[PTR_WIDTH-1]) &&
               (wgray[PTR_WIDTH-2] != rbin_sync[PTR_WIDTH-2]) &&
               (wgray[PTR_WIDTH-3:0] == rbin_sync[PTR_WIDTH-3:0]);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wbin <= 0;
    else if (winc && !wfull) wbin <= wbin + 1;
end

