always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wgray_sync[0] <= 0;
        wgray_sync[1] <= 0;
    end else begin
        wgray_sync[0] <= wgray;
        wgray_sync[1] <= wgray_sync[0];
