module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;

        EMPTY <= 1'b1;
        FULL <= 1'b0;
        for (i = 0;
 i < 4;
 i = i + 1) 
            stack_mem[i] <= 4'b0;
    end
    else if (EN) begin
        reg [2:0] next_SP = SP;
        reg [3:0] next_dataOut = dataOut;

        if (RW) begin 
            if (!EMPTY) begin
                next_dataOut = stack_mem[SP-1];
                stack_mem[SP-1] <= 4'b0;

                next_SP = SP - 1;
            end
        end
        else begin 
            if (!FULL) begin
                stack_mem[SP] <= dataIn;
                next_SP = SP + 1;
            end
        end


        dataOut <= next_dataOut;
        SP <= next_SP;
        EMPTY <= (next_SP == 0);
        FULL <= (next_SP == 4);
    end
end

endmodule

