module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] result;
    reg [32:0] sum;
    reg [31:0] slt;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum = {1'b0, a} + {1'b0, b};
                result = sum[31:0];
                {carry, overflow} = {sum[32], (a[31] == b[31]) && (result[31] != a[31])};
            end
            ADDU: begin
                {carry, result} = {1'b0, a} + {1'b0, b};
                overflow = 0;
            end
            SUB: begin
                sum = {1'b0, a} - {1'b0, b};
                result = sum[31:0];
                {carry, overflow} = {~sum[32], (a[31] != b[31]) && (result[31] != a[31])};
            end
            SUBU: begin
                {carry, result} = {1'b0, a} - {1'b0, b};
                overflow = 0;
            end
            AND: {carry, overflow, result} = {0, 0, a & b};
            OR:  {carry, overflow, result} = {0, 0, a | b};
            XOR: {carry, overflow, result} = {0, 0, a ^ b};
            NOR: {carry, overflow, result} = {0, 0, ~(a | b)};
            SLT: {carry, overflow, slt} = {0, 0, ($signed(a) < $signed(b)) ? 1 : 0};
            SLTU:{carry, overflow, slt} = {0, 0, (a < b) ? 1 : 0};
            SLL: result = a << b[4:0];
            SRL: result = a >> b[4:0];
            SRA: result = $signed(a) >>> b[4:0];
            SLLV: result = a << b[4:0];
            SRLV: result = a >> b[4:0];
            SRAV: result = $signed(a) >>> b[4:0];
            LUI: result = {b[15:0], 16'b0};
            default: result = 32'bz;
        endcase
    end

    assign {carry, overflow} = (aluc == SLT || aluc == SLTU) ? {1'b0, 1'b0} : {carry, overflow};
    assign {r, zero, negative} = {result, result == 0, result[31]};
    assign flag = (aluc == SLT || aluc == SLTU) ? slt[0] : 1'bz;

endmodule

