module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs, divisor_abs;
    reg sign_dividend, sign_divisor;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_dividend <= sign ? dividend[7] : 0;
                sign_divisor <= sign ? divisor[7] : 0;
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -divisor_abs;


                SR <= {9'b0, dividend_abs, 1'b0};

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 0;
                    cnt <= 0;
                    res_valid <= 1;


                    if (sign) begin
                        reg [8:0] remainder = SR[16:9];
                        reg [7:0] quotient = SR[8:1];
                        reg [8:0] signed_remainder = sign_dividend ? -remainder : remainder;
                        reg [7:0] signed_quotient = (sign_dividend ^ sign_divisor) ? -quotient : quotient;

                        result <= {signed_remainder[7:0], signed_quotient};
                    end else begin
                        result <= {SR[16:9][7:0], SR[8:1]};
                    end
                end else begin

                    reg [8:0] temp_remainder = {SR[15:9], SR[8]} << 1;
                    reg [7:0] temp_quotient = SR[8:1];
                    reg [8:0] sub_result = temp_remainder - divisor_abs;

                    if (sub_result[8] == 0) begin 
                        temp_remainder = sub_result;
                        temp_quotient = {temp_quotient[6:0], 1'b1};
                    end else begin
                        temp_quotient = {temp_quotient[6:0], 1'b0};
                    end

                    SR <= {temp_remainder, temp_quotient};
                    cnt <= cnt + 1;
                end
            end
        end
    end

endmodule

