reg [PTR_WIDTH-1:0] rptr_bin;
wire [ADDR_WIDTH-1:0] raddr_bin = rptr_bin[ADDR_WIDTH-1:0];


wire [PTR_WIDTH-1:0] wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
wire [PTR_WIDTH-1:0] rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


function [PTR_WIDTH-1:0] gray2bin;
    input [PTR_WIDTH-1:0] gray;
    integer i;
    begin
        gray2bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction

wire [PTR_WIDTH-1:0] wptr_bin_sync = gray2bin(wptr_gray_sync2);
wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync2);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        wptr_bin <= 0;
    else if (winc && !wfull)
        wptr_bin <= wptr_bin + 1;
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        rptr_bin <= 0;
    else if (rinc && !rempty)
        rptr_bin <= rptr_bin + 1;
