                    s2_yellow = 2'b10,
                    s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle:    next_state = s1_red;
            s1_red:  next_state = (cnt == 8'd0) ? s3_green : s1_red;
            s3_green:next_state = (cnt == 8'd0) ? s2_yellow : s3_green;
            s2_yellow:next_state = (cnt == 8'd0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (green && (state != s3_green)) begin
                cnt <= 8'd60;
            end else if (yellow && (state != s2_yellow)) begin
                cnt <= 8'd5;
            end else if (red && (state != s1_red)) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1'b1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
