module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= a;
        rise <= 0;
        down <= 0;
    end else begin
        a_prev <= a;
        if (a_prev == 1'b0 && a == 1'b1) begin
            rise <= 1;
            down <= 0;
        end else if (a_prev == 1'b1 && a == 1'b0) begin
            rise <= 0;
            down <= 1;
        end else begin
            rise <= 0;
            down <= 0;
        end
    end
end

endmodule

