module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] NEG_DIVISOR;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg sign_q, remainder_sign;


    reg [1:0] state;
    localparam IDLE = 0, PROCESSING = 1, DONE = 2;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            NEG_DIVISOR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            sign_q <= 0;
            remainder_sign <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                            remainder_sign <= dividend[7];
                            sign_q <= dividend[7] ^ divisor[7];
                        end else begin
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                            remainder_sign <= 0;
                            sign_q <= 0;
                        end
                        NEG_DIVISOR <= -abs_divisor;

                        SR <= {abs_dividend, 8'b0} << 1;
                        cnt <= 1;
                        state <= PROCESSING;
                    end
                end

                PROCESSING: begin
                    if (cnt == 8) begin

                        if (sign) begin
                            result[7:0] <= sign_q ? -SR[7:0] : SR[7:0];
                            result[15:8] <= remainder_sign ? SR[15:8] : -SR[15:8];
                        end else begin
                            result <= SR;
                        end
                        res_valid <= 1;
                        state <= DONE;
                    end else begin

                        reg [8:0] temp_remainder;
                        temp_remainder = {1'b0, SR[15:8]} - {1'b0, abs_divisor};
                        if (temp_remainder[8] == 0) begin
                            SR[15:8] <= temp_remainder[7:0];
                            SR[7:0] <= (SR[7:0] << 1) | 1;
                        end else begin
                            SR[7:0] <= SR[7:0] << 1;
                        end
                        cnt <= cnt + 1;
                    end
                end

                DONE: begin
                    if (!opn_valid) begin
                        res_valid <= 0;
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    initial begin
        state = IDLE;
        res_valid = 0;
        SR = 0;
        cnt = 0;
        NEG_DIVISOR = 0;
        abs_dividend = 0;
        abs_divisor = 0;
        sign_q = 0;
        remainder_sign = 0;
        result = 0;
    end

endmodule

