    reg [7:0] b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] rem;
        reg [15:0] q;
        integer i;

        rem = a_reg;
        q = 0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = rem << 1;
            if (rem >= {8'b0, b_reg}) begin
                rem = rem - {8'b0, b_reg};
                q[i] = 1'b1;
            end else begin
                q[i] = 1'b0;
            end
        end

        result = q;
        odd = rem;
    end

endmodule

