module fixed_point_adder #(
    parameter Q = 4, 
    parameter N = 8  
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire signs_same = (a_sign == b_sign);

    wire [N-1:0] a_mag = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_mag = b_sign ? (~b + 1) : b;

    wire [N-1:0] sum_same = a + b;

    wire [N-1:0] abs_diff;
    wire result_sign;

    always @(*) begin
        if (signs_same) begin
            res = sum_same;
        end else begin
            if (a_mag > b_mag) begin
                abs_diff = a_mag - b_mag;
                result_sign = a_sign;
            end else if (b_mag > a_mag) begin
                abs_diff = b_mag - a_mag;
                result_sign = b_sign;
            end else begin
                abs_diff = {N{1'b0}};
                result_sign = 1'b0;
            end
            res = result_sign ? (~abs_diff + 1) : abs_diff;
        end
    end

    assign c = res;

endmodule

