module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exp, b_exp, z_exp;
reg [22:0] a_man, b_man;
reg [47:0] product;
reg [23:0] combined_man;
reg guard_bit, round_bit, sticky;
reg [9:0] combined_exp;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'd0;
    end else begin
        case (counter)

            3'b000: begin
                a_sign <= a[31];
                a_exp <= a[30:23];
                a_man <= a[22:0];
                b_sign <= b[31];
                b_exp <= b[30:23];
                b_man <= b[22:0];


                if ((a_exp == 8'hff && a_man != 0) || (b_exp == 8'hff && b_man != 0)) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                end else if ((a_exp == 8'hff && b_exp != 8'hff) || (b_exp == 8'hff && a_exp != 8'hff)) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                end else if (a == 32'd0 || b == 32'd0) begin
                    z <= {a_sign ^ b_sign, 31'd0};
                end else begin
                    counter <= 3'b001;
                end
            end


            3'b001: begin
                combined_man <= {1'b1, a_man} * {1'b1, b_man};
                counter <= 3'b010;
            end


            3'b010: begin
                integer i;
                reg [5:0] shift;
                shift = 0;
                for (i = 47;
 i >= 0;
 i = i - 1) begin
                    if (combined_man[i]) begin
                        shift = 47 - i;
                        break;
                    end
                end
                combined_exp <= a_exp + b_exp + shift - 127;
                product <= combined_man >> shift;

                counter <= 3'b011;
            end


            3'b011: begin
                guard_bit <= product[24];
                round_bit <= product[23];
                sticky <= |product[22:0];

                if (guard_bit && (round_bit || sticky)) begin
                    combined_man <= {1'b1, product[47:25]} + 1;
                end else begin
                    combined_man <= {1'b1, product[47:25]};
                end

                counter <= 3'b100;
            end


            3'b100: begin
                if (combined_exp[9:8] == 2'b11) begin
                    z <= {z_sign, 8'hff, 23'h0};

                end else if (combined_exp[7:0] == 8'd0) begin
                    z <= {z_sign, 31'd0};

                end else begin
                    z <= {z_sign, combined_exp[7:0], combined_man[22:0]};
                end
                counter <= 3'b000;
            end

            default: counter <= 3'b000;
        endcase
    end
end

endmodule

