                    data_reg <= data_reg << 1;
                    counter <= counter + 1;
                    dout <= data_reg[3];
                end
            end else begin
                data_reg <= d;
                counter <= 2'b00;
                valid_out <= 1'b1;
                dout <= d[3];
            end
        end
    end

