module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg state;
localparam IDLE = 0;
localparam CHECK_1 = 1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                data_out <= 0;
                state <= (data_in) ? CHECK_1 : IDLE;
            end
            CHECK_1: begin
                if (data_in) begin
                    state <= CHECK_1;
                    data_out <= 0;
                end else begin
                    state <= IDLE;
                    data_out <= 1;
                end
            end
            default: state <= IDLE;
        endcase
    end
end

