module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;

always @(posedge clk) begin
    if (!rst_n) begin
        a_prev <= a;
        rise <= 0;
        down <= 0;
    end else begin
        if (a != a_prev) begin
            if (a == 1'b1) begin
                rise <= 1'b1;
                down <= 1'b0;
            end else begin
                rise <= 1'b0;
                down <= 1'b1;
            end
        end else begin
            rise <= 1'b0;
            down <= 1'b0;
        end
        a_prev <= a;
    end
end

endmodule

