module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    reg [32:0] add_sub_result;
    reg [4:0] shift_amount;


    always @(*) begin
        r = 32'b0;
        carry = 1'b0;
        overflow = 1'b0;

        case (aluc)
            ADD: begin
                add_sub_result = {1'b0, a} + {1'b0, b};
                r = add_sub_result[31:0];
                carry = add_sub_result[32];
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                r = a + b;
                carry = (r < a);

            end
            SUB: begin
                add_sub_result = {1'b0, a} - {1'b0, b};
                r = add_sub_result[31:0];
                carry = add_sub_result[32];
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                r = a - b;
                carry = (a >= b);

            end
            AND: r = a & b;
            OR:  r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: begin
                r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                overflow = 1'b0;
                carry = 1'b0;
            end
            SLTU: begin
                r = (a < b) ? 32'd1 : 32'd0;
                overflow = 1'b0;
                carry = 1'b0;
            end
            SLL: begin
                shift_amount = a[4:0];
                r = b << shift_amount;
            end
            SRL: begin
                shift_amount = a[4:0];
                r = b >> shift_amount;
            end
            SRA: begin
                shift_amount = a[4:0];
