module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [1:0] state;
localparam IDLE = 0;
localparam BUSY = 1;
localparam ADJUST = 2;

reg [7:0] abs_dividend, abs_divisor;
reg sign_q, sign_r;
reg [15:0] rq;

reg [3:0] cnt;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        rq <= 0;
        cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        sign_q <= 0;
        sign_r <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                        abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                        sign_q <= (dividend[7] ^ divisor[7]);
                        sign_r <= dividend[7];
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                        sign_q <= 0;
                        sign_r <= 0;
                    end
                    rq <= {8'b0, abs_dividend};
                    cnt <= 0;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (cnt < 8) begin

                    rq <= {rq[14:0], 1'b0};


                    if (rq[15:8] >= abs_divisor) begin
                        rq[15:8] <= rq[15:8] - abs_divisor;
                        rq[0] <= 1'b1;
                    end

                    cnt <= cnt + 1;
                end else begin
                    state <= ADJUST;
                end
            end
            ADJUST: begin

                if (sign_r) begin
                    if (rq[15:8] != 0)
                        rq[15:8] <= ~rq[15:8] + 1;
                end


                if (sign_q) begin
                    if (rq[7:0] != 0)
                        rq[7:0] <= ~rq[7:0] + 1;
                end

                result <= rq;
                res_valid <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

