    reg [23:0] man_product;

    reg guard, round, sticky;
    reg [7:0] exp_temp;
    reg [7:0] exp_adjust;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exp <= 0;
            b_exp <= 0;
            a_man <= 0;
            b_man <= 0;
            product <= 0;
            man_product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            exp_temp <= 0;
            exp_adjust <= 0;
            z_sign <= 0;
            z_exp <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_man <= {1'b1, a[22:0]};
                    b_man <= {1'b1, b[22:0]};
