    parameter S0 = 3'b000,
              S1 = 3'b001,
              S2 = 3'b010,
              S3 = 3'b011,
              S4 = 3'b100;


    always @(posedge CLK) begin
        if (RST) current_state <= S0;
        else current_state <= next_state;
