    wire [3:0] wgray, rgray;
    reg [3:0] rgray_sync1, rgray_sync;
    reg [3:0] wgray_sync1, wgray_sync;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wbin <= 0;
        end else if (winc && !wfull) begin
            wbin <= wbin + 1;
        end
