module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle    = 2'b00,
          s1_red  = 2'b01,
          s2_yellow = 2'b10,
          s3_green  = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 8'd10;
    end else begin
        case (state)
            idle: begin
                state <= s1_red;
            end
            s1_red: begin
                if (cnt == 0) state <= s3_green;
                else cnt <= cnt - 1;
            end
            s3_green: begin
                if (cnt == 0) state <= s2_yellow;
                else cnt <= cnt - 1;
            end
            s2_yellow: begin
                if (cnt == 0) state <= s1_red;
                else cnt <= cnt - 1;
            end
            default: state <= idle;
        endcase


        if (pass_request && p_green) begin
            if (cnt > 8'd10) cnt <= 8'd10;
        end else begin
            case (state)
                idle:    cnt <= 8'd10;
                s1_red:  cnt <= (cnt == 0) ? 8'd10 : (pass_request ? 8'd10 : cnt - 1);
                s3_green: cnt <= (cnt == 0) ? 8'd60 : (pass_request ? 8'd10 : cnt - 1);
                s2_yellow: cnt <= (cnt == 0) ? 8'd5 : (pass_request ? 8'd10 : cnt - 1);
                default: cnt <= 8'd10;
            endcase
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
        clock <= 0;
    end else begin
        clock <= cnt;
        case (state)
            idle: begin
                red <= 0;
                yellow <= 0;
                green <= 0;
            end
            s1_red: red <= 1;
            s3_green: green <= 1;
            s2_yellow: yellow <= 1;
            default: begin
                red <= 0;
                yellow <= 0;
                green <= 0;
            end
        endcase
    end
end

endmodule

