module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] buffer;
reg state;
reg [15:0] data_reg;
reg valid_reg;

localparam IDLE = 1'b0;
localparam HAVE_FIRST = 1'b1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        buffer <= 8'b0;
        valid_reg <= 0;
        data_reg <= 16'b0;
        valid_out <= 0;
        data_out <= 16'b0;
    end
    else begin
        valid_out <= valid_reg;
        data_out <= data_reg;

        case (state)
            IDLE: begin
                if (valid_in) begin
                    buffer <= data_in;
                    state <= HAVE_FIRST;
                    valid_reg <= 0;
                end
            end
            HAVE_FIRST: begin
                if (valid_in) begin
                    data_reg <= {buffer, data_in};
                    valid_reg <= 1;
                    state <= IDLE;
                end
            end
            default: state <= IDLE;
        endcase
    end
end

