module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire eq;
    wire A_gt_term3, A_gt_term2, A_gt_term1, A_gt_term0;
    wire A_lt_term3, A_lt_term2, A_lt_term1, A_lt_term0;

    assign eq = (A == B);

    assign A_gt_term3 = (A[3] & ~B[3]);
    assign A_gt_term2 = (A[3] ~^ B[3]) & (A[2] & ~B[2]);
    assign A_gt_term1 = (A[3] ~^ B[3]) & (A[2] ~^ B[2]) & (A[1] & ~B[1]);
    assign A_gt_term0 = (A[3] ~^ B[3]) & (A[2] ~^ B[2]) & (A[1] ~^ B[1]) & (A[0] & ~B[0]);

    assign A_greater = A_gt_term3 | A_gt_term2 | A_gt_term1 | A_gt_term0;

    assign A_lt_term3 = (B[3] & ~A[3]);
    assign A_lt_term2 = (A[3] ~^ B[3]) & (B[2] & ~A[2]);
    assign A_lt_term1 = (A[3] ~^ B[3]) & (A[2] ~^ B[2]) & (B[1] & ~A[1]);
    assign A_lt_term0 = (A[3] ~^ B[3]) & (A[2] ~^ B[2]) & (A[1] ~^ B[1]) & (B[0] & ~A[0]);

    assign A_less = A_lt_term3 | A_lt_term2 | A_lt_term1 | A_lt_term0;

    assign A_equal = eq;

