    reg [64:0] sum_reg;
    reg en_stage1, en_stage2;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            adda_reg <= 64'b0;
            addb_reg <= 64'b0;
            en_stage1 <= 1'b0;
        end else if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
            en_stage1 <= 1'b1;
        end else begin
            en_stage1 <= 1'b0;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_reg <= 65'b0;
            en_stage2 <= 1'b0;
        end else if (en_stage1) begin
            sum_reg <= {1'b0, adda_reg} + {1'b0, addb_reg};
            en_stage2 <= 1'b1;
        end else begin
            en_stage2 <= 1'b0;
        end
    end


    reg [1:0] en_pipe;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            en_pipe <= 2'b00;
        end else begin
            en_pipe <= {en_pipe[0], en_stage2};
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 65'b0;
            o_en <= 1'b0;
        end else begin
            result <= sum_reg;
            o_en <= en_pipe[1];
        end
    end

endmodule

