module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input C0,
    output [4:1] S,
    output G,
    output P
);
    wire [4:1] g = A & B;
    wire [4:1] p = A ^ B;

    wire c1 = g[1] | (p[1] & C0);
    wire c2 = g[2] | (p[2] & g[1]) | (p[2] & p[1] & C0);
    wire c3 = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & C0);
    wire c4 = g[4] | (p[4] & g[3]) | (p[4] & p[3] & g[2]) | (p[4] & p[3] & p[2] & g[1]) | (p[4] & p[3] & p[2] & p[1] & C0);

    assign S = { (p[4] ^ c4), (p[3] ^ c3), (p[2] ^ c2), (p[1] ^ c1) };

    assign G = g[4] | (p[4] & g[3]) | (p[4] & p[3] & g[2]) | (p[4] & p[3] & p[2] & g[1]);
    assign P = p[4] & p[3] & p[2] & p[1];
endmodule

