    wire [3:1] group_p;
    wire [4:1] carry;

    cla_4bit cla0 (
        .A(A[4:1]),
        .B(B[4:1]),
        .C0(C0),
        .S(S[4:1]),
        .G(group_g[1]),
        .P(group_p[1]),
        .C16()
    );

    cla_4bit cla1 (
        .A(A[8:5]),
        .B(B[8:5]),
        .C0(carry[1]),
        .S(S[8:5]),
        .G(group_g[2]),
        .P(group_p[2]),
        .C16()
    );

    cla_4bit cla2 (
        .A(A[12:9]),
        .B(B[12:9]),
        .C0(carry[2]),
        .S(S[12:9]),
        .G(group_g[3]),
        .P(group_p[3]),
        .C16()
    );

    cla_4bit cla3 (
        .A(A[16:13]),
        .B(B[16:13]),
        .C0(carry[3]),
        .S(S[16:13]),
        .G(group_g[4]),
        .P(group_p[4]),
        .C16()
    );

    assign carry[1] = group_g[1] | (group_p[1] & C0);
    assign carry[2] = group_g[2] | (group_p[2] & carry[1]);
    assign carry[3] = group_g[3] | (group_p[3] & carry[2]);
    assign carry[4] = group_g[4] | (group_p[4] & carry[3]);

    assign G = group_g[4] | (group_p[4] & group_g[3]) | (group_p[4] & group_p[3] & group_g[2]) | (group_p[4] & group_p[3] & group_p[2] & group_g[1]);
    assign P = group_p[4] & group_p[3] & group_p[2] & group_p[1];
    assign C16 = G | (P & C0);
endmodule

