module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;


wire [N-2:0] abs_a = a[N-1] ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] abs_b = b[N-1] ? (~b[N-2:0] + 1) : b[N-2:0];


wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);


wire [N:0] sum_abs = {1'b0, abs_a} + {1'b0, abs_b};
wire [N-2:0] sum_trunc = sum_abs[N-1:0];


wire [N-2:0] sub_result;
wire sub_sign;
if (abs_a > abs_b) begin
    assign sub_result = abs_a - abs_b;
    assign sub_sign = sign_a;
end else if (abs_b > abs_a) begin
    assign sub_result = abs_b - abs_a;
    assign sub_sign = sign_b;
end else begin
    assign sub_result = 0;
    assign sub_sign = 0;
end


always @(*) begin
    if (same_sign) begin
        res = {sign_a, sum_trunc};

        if (sum_abs[N]) res = {~sign_a, sum_trunc};
    end else begin
        res = {sub_sign, sub_result};
    end
end

assign c = res;

endmodule

