module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg sign_a, sign_b;
reg [N-Q-1:0] integer_a, integer_b;
reg [Q-1:0] fractional_a, fractional_b;
reg [N-Q-1:0] integer_res;
reg [Q-1:0] fractional_res;
reg res_sign;

always @(*) begin
    sign_a = a[N-1];
    integer_a = a[N-2:N-Q];
    fractional_a = a[Q-1:0];
    sign_b = b[N-1];
    integer_b = b[N-2:N-Q];
    fractional_b = b[Q-1:0];

    if (sign_a == sign_b) begin
        if (integer_a >= integer_b) begin
            integer_res = integer_a - integer_b;
            fractional_res = fractional_a - fractional_b;
            if (fractional_res[Q-1]) begin 
                integer_res = integer_res - 1;
                fractional_res = fractional_res + (1 << Q);
            end
            res_sign = sign_a;
        end else begin
            integer_res = integer_b - integer_a;
            fractional_res = fractional_b - fractional_a;
            if (fractional_res[Q-1]) begin 
                integer_res = integer_res - 1;
                fractional_res = fractional_res + (1 << Q);
            end
            res_sign = sign_a;
        end
    end else begin
        if (integer_a > integer_b) begin
            integer_res = integer_a + integer_b;
            fractional_res = fractional_a + fractional_b;
            if (fractional_res[Q-1]) begin 
                integer_res = integer_res + 1;
                fractional_res = fractional_res - (1 << Q);
            end
            res_sign = sign_a;
        end else if (integer_a < integer_b) begin
            integer_res = integer_b + integer_a;
            fractional_res = fractional_b + fractional_a;
            if (fractional_res[Q-1]) begin 
                integer_res = integer_res + 1;
                fractional_res = fractional_res - (1 << Q);
            end
            res_sign = sign_b;
        end else begin
            if (fractional_a > fractional_b) begin
                integer_res = 0;
                fractional_res = fractional_a - fractional_b;
                res_sign = sign_a;
            end else if (fractional_a < fractional_b) begin
                integer_res = 0;
                fractional_res = fractional_b - fractional_a;
                res_sign = sign_b;
            end else begin
                integer_res = 0;
                fractional_res = 0;
                res_sign = 0;
            end
        end
    end

    c[N-1] = res_sign;
    c[N-2:N-Q] = integer_res;
    c[Q-1:0] = fractional_res;

    if (integer_res == 0 && fractional_res == 0) begin
        c[N-1] = 0;
    end
end

endmodule

