module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;

    reg [4:0] exp_sum;
    reg [47:0] normalized_product;
    reg [4:0] shift;
    reg [23:0] rounded_mantissa;


    wire a_zero = (a[30:23] == 0) && (a[22:0] == 0);
    wire b_zero = (b[30:23] == 0) && (b[22:0] == 0);
    wire a_inf = (a[30:23] == 8'hff) && (a[22:0] == 0);
    wire b_inf = (b[30:23] == 8'hff) && (b[22:0] == 0);
    wire a_nan = (a[30:23] == 8'hff) && (a[22:0] != 0);
    wire b_nan = (b[30:23] == 8'hff) && (b[22:0] != 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];

                    if (a_zero || b_zero || a_inf || b_inf || a_nan || b_nan) begin

                        if (a_nan || b_nan) begin
                            z <= {1'b0, 8'hff, 1'b1, 22'h0};

                        end else if (a_inf && b_zero) begin
                            z <= {1'b0, 8'hff, 1'b1, 22'h0};

                        end else if (b_inf && a_zero) begin
                            z <= {1'b0, 8'hff, 1'b1, 22'h0};

                        end else if (a_inf || b_inf) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 31'h0};

                        end
                    end else begin

                        counter <= 1;
                    end
                end
                1: begin

                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    exp_sum <= a_exponent + b_exponent - 8'd127;
                    counter <= 2;
                end
                2: begin

                    normalized_product = product;

                    shift = 0;
                    for (integer i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            shift = 47 - i;
                            normalized_product = product << shift;
                            break;
                        end
                    end
                    exp_sum <= exp_sum + shift;
                    counter <= 3;
                end
                3: begin

                    guard <= normalized_product[23];
                    round <= normalized_product[22];
                    sticky <= |normalized_product[21:0];

                    if (guard & (round | sticky | normalized_product[24])) begin
                        rounded_mantissa = {normalized_product[24:1], 1'b1} + 1;
                    end else begin
                        rounded_mantissa = normalized_product[24:1];
                    end
                    counter <= 4;
                end
                4: begin

                    if (exp_sum[9:0] > 8'hfe) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (exp_sum[9:0] < 9'h1) begin

                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin

                        z <= {a_sign ^ b_sign, exp_sum[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

